window.QBANK = window.QBANK || {};
window.QBANK["smp-pai"] = {
  level: "SMP", subject: "Pendidikan Agama", duration: 900,
  questions: [
    { q: "Jumlah rukun iman ada ....", options: ["Lima", "Enam", "Tujuh", "Empat"], answer: 1, solution: "1. Rukun iman adalah pokok-pokok kepercayaan yang wajib diimani setiap muslim. 2. Jumlahnya ada enam: iman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, rasul-rasul-Nya, hari akhir, serta qadha dan qadar. 3. Jadi jawabannya enam (lima adalah jumlah rukun Islam, jangan tertukar)." },
    { q: "Berikut ini yang bukan termasuk rukun iman adalah ....", options: ["Iman kepada Allah SWT", "Iman kepada malaikat-malaikat-Nya", "Iman kepada salat", "Iman kepada hari akhir"], answer: 2, solution: "1. Rukun iman ada enam, di antaranya iman kepada Allah, malaikat, dan hari akhir. 2. Salat adalah ibadah pokok yang termasuk rukun Islam, bukan rukun iman. 3. Jadi yang bukan rukun iman adalah iman kepada salat." },
    { q: "Malaikat yang bertugas menyampaikan wahyu kepada para rasul adalah ....", options: ["Mikail", "Jibril", "Israfil", "Izrail"], answer: 1, solution: "1. Setiap malaikat memiliki tugas masing-masing: Mikail membagi rezeki, Israfil meniup sangkakala, Izrail mencabut nyawa. 2. Malaikat yang menyampaikan wahyu dari Allah kepada para rasul adalah Jibril. 3. Jadi jawabannya Jibril." },
    { q: "Kitab suci yang diturunkan Allah kepada Nabi Musa AS adalah ....", options: ["Zabur", "Injil", "Taurat", "Al-Qur'an"], answer: 2, solution: "1. Empat kitab yang wajib diimani adalah Taurat, Zabur, Injil, dan Al-Qur'an. 2. Taurat diturunkan kepada Nabi Musa AS, Zabur kepada Nabi Daud AS, Injil kepada Nabi Isa AS, dan Al-Qur'an kepada Nabi Muhammad SAW. 3. Jadi kitab Nabi Musa AS adalah Taurat." },
    { q: "Nabi yang menerima kitab Zabur adalah ....", options: ["Nabi Daud AS", "Nabi Musa AS", "Nabi Isa AS", "Nabi Ibrahim AS"], answer: 0, solution: "1. Kitab Zabur diturunkan Allah kepada salah satu nabi dan rasul-Nya. 2. Penerima kitab Zabur adalah Nabi Daud AS (Nabi Musa AS menerima Taurat, Nabi Isa AS menerima Injil). 3. Jadi jawabannya Nabi Daud AS." },
    { q: "Iman kepada qadha dan qadar merupakan rukun iman yang ke-....", options: ["Ketiga", "Keempat", "Keenam", "Kelima"], answer: 2, solution: "1. Urutan rukun iman: 1) iman kepada Allah, 2) malaikat, 3) kitab-kitab, 4) rasul-rasul, 5) hari akhir, 6) qadha dan qadar. 2. Iman kepada qadha dan qadar berada pada urutan terakhir. 3. Jadi jawabannya rukun iman yang keenam." },
    { q: "Berikut ini yang tidak termasuk rasul Ulul Azmi adalah ....", options: ["Nabi Nuh AS", "Nabi Ibrahim AS", "Nabi Musa AS", "Nabi Yusuf AS"], answer: 3, solution: "1. Rasul Ulul Azmi adalah rasul yang memiliki ketabahan dan kesabaran luar biasa dalam berdakwah, jumlahnya lima. 2. Kelimanya adalah Nabi Nuh AS, Nabi Ibrahim AS, Nabi Musa AS, Nabi Isa AS, dan Nabi Muhammad SAW. 3. Nabi Yusuf AS adalah rasul, tetapi tidak termasuk Ulul Azmi." },
    { q: "Iman kepada qadha dan qadar artinya meyakini bahwa ....", options: ["Segala sesuatu terjadi atas ketetapan Allah SWT", "Manusia bebas menentukan segalanya tanpa campur tangan Allah", "Nasib manusia ditentukan oleh pergerakan bintang", "Allah tidak mengetahui apa yang akan terjadi di masa depan"], answer: 0, solution: "1. Qadha adalah ketetapan Allah, sedangkan qadar adalah ukuran atau kadar dari ketetapan itu. 2. Beriman kepada keduanya berarti meyakini bahwa segala sesuatu yang terjadi, baik dan buruk, atas ketetapan dan sepengetahuan Allah SWT. 3. Manusia tetap wajib berusaha, tetapi hasilnya adalah ketetapan Allah." },
    { q: "Sifat wajib bagi rasul yang artinya menyampaikan wahyu kepada umatnya adalah ....", options: ["Siddiq", "Amanah", "Tabligh", "Fathanah"], answer: 2, solution: "1. Sifat wajib rasul ada empat: siddiq (jujur), amanah (dapat dipercaya), tabligh (menyampaikan), dan fathanah (cerdas). 2. Sifat yang artinya menyampaikan wahyu Allah kepada umat manusia adalah tabligh. 3. Lawannya adalah kitman (menyembunyikan wahyu), sifat mustahil bagi rasul." },
    { q: "Jumlah rukun Islam ada ....", options: ["Empat", "Lima", "Enam", "Tujuh"], answer: 1, solution: "1. Rukun Islam adalah pokok-pokok ajaran Islam yang wajib dilaksanakan. 2. Jumlahnya ada lima: syahadat, salat, zakat, puasa Ramadan, dan haji. 3. Jadi jawabannya lima (enam adalah jumlah rukun iman, jangan tertukar)." },
    { q: "Rukun Islam yang pertama adalah ....", options: ["Mendirikan salat lima waktu", "Membaca dua kalimat syahadat", "Menunaikan zakat", "Berpuasa di bulan Ramadan"], answer: 1, solution: "1. Urutan rukun Islam dimulai dari yang paling pokok, yaitu pengakuan keimanan. 2. Rukun Islam pertama adalah membaca dua kalimat syahadat sebagai pintu masuk Islam. 3. Salat, zakat, dan puasa adalah rukun berikutnya." },
    { q: "Urutan rukun Islam yang benar adalah ....", options: ["Salat, syahadat, zakat, puasa, haji", "Syahadat, salat, puasa, zakat, haji", "Syahadat, salat, zakat, puasa, haji", "Zakat, syahadat, salat, haji, puasa"], answer: 2, solution: "1. Urutan rukun Islam menurut hadis Nabi Muhammad SAW adalah: syahadat, salat, zakat, puasa, haji. 2. Urutan yang menukar zakat dan puasa adalah keliru. 3. Jadi urutan yang benar adalah syahadat, salat, zakat, puasa, haji." },
    { q: "Arti syahadat tauhid 'asyhadu alla ilaha illallah' adalah ....", options: ["Aku bersaksi bahwa Nabi Muhammad adalah utusan Allah", "Aku bersaksi bahwa tidak ada Tuhan selain Allah", "Aku berjanji akan selalu salat lima waktu", "Aku bersaksi bahwa Al-Qur'an adalah kitab suci terakhir"], answer: 1, solution: "1. Syahadat terdiri dari dua kalimat: syahadat tauhid dan syahadat rasul. 2. 'Asyhadu alla ilaha illallah' adalah syahadat tauhid yang artinya aku bersaksi bahwa tidak ada Tuhan yang berhak disembah selain Allah. 3. Kalimat tentang Nabi Muhammad adalah syahadat rasul." },
    { q: "Seseorang dinyatakan resmi masuk Islam setelah ....", options: ["Mengucapkan dua kalimat syahadat dengan yakin dan paham maknanya", "Berpuasa sebulan penuh di bulan Ramadan", "Bersedekah kepada fakir miskin", "Menghafal seluruh ayat Al-Qur'an"], answer: 0, solution: "1. Pintu masuk Islam adalah dua kalimat syahadat. 2. Seseorang menjadi muslim setelah mengucapkan syahadat dengan yakin, paham maknanya, dan tanpa paksaan. 3. Puasa, sedekah, dan menghafal Al-Qur'an adalah amalan setelah menjadi muslim." },
    { q: "Jumlah rakaat salat Subuh adalah ....", options: ["Dua rakaat", "Tiga rakaat", "Empat rakaat", "Satu rakaat"], answer: 0, solution: "1. Salat wajib lima waktu memiliki jumlah rakaat yang tetap. 2. Salat Subuh dikerjakan sebanyak dua rakaat. 3. Jadi jawabannya dua rakaat (tiga rakaat adalah salat Maghrib)." },
    { q: "Jumlah rakaat salat Maghrib adalah ....", options: ["Dua rakaat", "Tiga rakaat", "Empat rakaat", "Lima rakaat"], answer: 1, solution: "1. Setiap salat wajib memiliki jumlah rakaat tertentu. 2. Salat Maghrib dikerjakan sebanyak tiga rakaat. 3. Jadi jawabannya tiga rakaat (dua rakaat adalah salat Subuh)." },
    { q: "Jumlah rakaat salat Isya adalah ....", options: ["Dua rakaat", "Tiga rakaat", "Empat rakaat", "Lima rakaat"], answer: 2, solution: "1. Salat Isya adalah salat wajib terakhir dalam sehari. 2. Jumlah rakaat salat Isya adalah empat rakaat, sama seperti salat Zuhur dan Asar. 3. Jadi jawabannya empat rakaat." },
    { q: "Jumlah seluruh rakaat salat wajib dalam sehari semalam adalah ....", options: ["Lima belas rakaat", "Enam belas rakaat", "Tujuh belas rakaat", "Delapan belas rakaat"], answer: 2, solution: "1. Hitung rakaat tiap salat wajib: Subuh 2, Zuhur 4, Asar 4, Maghrib 3, Isya 4. 2. Jumlahkan: 2 + 4 + 4 + 3 + 4 = 17. 3. Jadi seluruh salat wajib sehari semalam berjumlah tujuh belas rakaat." },
    { q: "Berikut ini yang termasuk syarat salat adalah ....", options: ["Membaca surah Al-Fatihah", "Menutup aurat", "Rukuk dengan tuma'ninah", "Duduk tasyahud akhir"], answer: 1, solution: "1. Syarat salat adalah hal yang harus dipenuhi sebelum mengerjakan salat, sedangkan rukun salat dikerjakan di dalam salat. 2. Membaca Al-Fatihah, rukuk, dan tasyahud akhir dikerjakan di dalam salat sehingga termasuk rukun. 3. Menutup aurat dilakukan sebelum salat, jadi termasuk syarat salat." },
    { q: "Berikut ini yang termasuk rukun salat adalah ....", options: ["Berwudu sebelum salat", "Menghadap kiblat", "Membaca surah Al-Fatihah", "Suci badan dari najis"], answer: 2, solution: "1. Berwudu, menghadap kiblat, dan suci dari najis dikerjakan sebelum salat dimulai sehingga termasuk syarat salat. 2. Membaca surah Al-Fatihah dikerjakan di dalam salat pada setiap rakaat. 3. Jadi membaca Al-Fatihah termasuk rukun salat." },
    { q: "Hal yang membatalkan salat adalah ....", options: ["Menguap karena mengantuk", "Berbicara dengan sengaja", "Batuk ringan yang tidak disengaja", "Menangis karena takut kepada Allah"], answer: 1, solution: "1. Salat batal jika terjadi hal-hal tertentu, misalnya terkena hadats atau melakukan perbuatan yang dilarang. 2. Berbicara dengan sengaja membatalkan salat karena memutus kekhusyukan dan rangkaian salat. 3. Menguap, batuk ringan yang tidak disengaja, dan menangis karena takut kepada Allah tidak membatalkan salat." },
    { q: "Hukum melaksanakan salat Jumat bagi laki-laki muslim yang memenuhi syarat adalah ....", options: ["Wajib", "Sunah", "Mubah", "Makruh"], answer: 0, solution: "1. Salat Jumat dilaksanakan setiap hari Jumat dan menggantikan salat Zuhur. 2. Hukumnya wajib (fardu 'ain) bagi laki-laki muslim yang baligh, berakal, merdeka, sehat, dan tidak sedang bepergian jauh. 3. Jadi jawabannya wajib, bukan sunah." },
    { q: "Perintah salat lima waktu diterima Nabi Muhammad SAW pada peristiwa ....", options: ["Isra Mi'raj", "Hijrah ke Madinah", "Fathu Makkah", "Perang Badar"], answer: 0, solution: "1. Nabi Muhammad SAW diperjalankan Allah pada malam hari dari Masjidil Haram ke Masjidil Aqsa lalu ke Sidratul Muntaha. 2. Pada peristiwa Isra Mi'raj inilah beliau menerima perintah salat lima waktu. 3. Jadi jawabannya Isra Mi'raj." },
    { q: "Zakat fitrah dikeluarkan dalam bentuk ....", options: ["Emas dan perak", "Makanan pokok", "Pakaian baru", "Hewan ternak"], answer: 1, solution: "1. Zakat fitrah adalah zakat jiwa yang wajib dikeluarkan setiap bulan Ramadan. 2. Zakat fitrah dikeluarkan dalam bentuk makanan pokok yang biasa dimakan, misalnya beras di Indonesia. 3. Emas, pakaian, dan hewan ternak berkaitan dengan zakat mal, bukan zakat fitrah." },
    { q: "Besar zakat fitrah yang wajib dikeluarkan setiap jiwa adalah ....", options: ["Satu sha' (sekitar 2,5 kg beras)", "Dua sha' (sekitar 5 kg beras)", "Setengah sha' (sekitar 1 kg beras)", "Tiga sha' (sekitar 7,5 kg beras)"], answer: 0, solution: "1. Takaran zakat fitrah ditetapkan Nabi Muhammad SAW sebesar satu sha'. 2. Satu sha' setara dengan sekitar 2,5 kg atau 3,5 liter beras. 3. Jadi setiap jiwa wajib mengeluarkan satu sha' makanan pokok." },
    { q: "Kadar zakat mal yang wajib dikeluarkan adalah ....", options: ["2,5% dari harta yang mencapai nisab", "5% dari seluruh penghasilan", "7,5% dari harta simpanan", "10% dari hasil pertanian"], answer: 0, solution: "1. Zakat mal adalah zakat harta seperti uang, emas, dan barang dagangan. 2. Kadarnya adalah 2,5% dari harta yang telah mencapai nisab dan haul. 3. Jadi jawabannya 2,5%, bukan 5% atau 10%." },
    { q: "Golongan yang berhak menerima zakat (mustahik) berjumlah ....", options: ["Lima golongan", "Enam golongan", "Tujuh golongan", "Delapan golongan"], answer: 3, solution: "1. Mustahik zakat disebutkan dalam QS At-Taubah ayat 60. 2. Kedelapan golongan itu adalah fakir, miskin, amil, mualaf, riqab (hamba sahaya), gharim (orang berutang), fi sabilillah, dan ibnu sabil (musafir). 3. Jadi jumlahnya delapan golongan." },
    { q: "Syarat wajib zakat mal adalah harta telah ....", options: ["Dimiliki selama satu minggu", "Mencapai nisab dan haul", "Diberikan kepada tetangga", "Disimpan di dalam rumah"], answer: 1, solution: "1. Nisab adalah batas minimal jumlah harta yang wajib dizakati. 2. Haul adalah masa kepemilikan harta selama satu tahun hijriah. 3. Zakat mal wajib dikeluarkan jika harta telah mencapai nisab dan haul." },
    { q: "Puasa Ramadan merupakan rukun Islam yang ke-....", options: ["Ketiga", "Keempat", "Kelima", "Kedua"], answer: 1, solution: "1. Urutan rukun Islam: 1) syahadat, 2) salat, 3) zakat, 4) puasa, 5) haji. 2. Puasa di bulan Ramadan berada pada urutan keempat. 3. Jadi jawabannya rukun Islam yang keempat." },
    { q: "Hal yang membatalkan puasa adalah ....", options: ["Makan dan minum dengan sengaja", "Lupa lalu makan atau minum", "Berkumur-kumur saat berwudu", "Mencicipi masakan tanpa menelannya"], answer: 0, solution: "1. Puasa batal jika ada hal yang masuk ke dalam tubuh dengan sengaja. 2. Makan dan minum dengan sengaja membatalkan puasa. 3. Makan karena lupa, berkumur saat berwudu, dan mencicipi tanpa menelan tidak membatalkan puasa." },
    { q: "Wanita yang sedang haid pada bulan Ramadan wajib ....", options: ["Tetap berpuasa seperti biasa", "Tidak berpuasa dan menggantinya di hari lain (qadha)", "Membayar fidyah tanpa mengganti puasa", "Berpuasa setengah hari saja"], answer: 1, solution: "1. Wanita yang haid atau nifas tidak boleh berpuasa. 2. Ia wajib mengganti (qadha) puasa yang ditinggalkan pada hari lain di luar bulan Ramadan. 3. Fidyah hanya untuk orang yang tidak mampu berpuasa sama sekali, seperti orang tua renta." },
    { q: "Niat puasa Ramadan dilakukan pada ....", options: ["Siang hari setelah makan siang", "Malam hari sebelum terbit fajar", "Sore hari menjelang berbuka", "Pagi hari setelah sarapan"], answer: 1, solution: "1. Puasa Ramadan wajib diawali dengan niat. 2. Niat puasa Ramadan dilakukan pada malam hari sebelum terbit fajar. 3. Berniat setelah fajar terbit tidak sah untuk puasa wajib Ramadan." },
    { q: "Ibadah haji merupakan rukun Islam yang ke-....", options: ["Ketiga", "Keempat", "Kelima", "Kedua"], answer: 2, solution: "1. Urutan rukun Islam: 1) syahadat, 2) salat, 3) zakat, 4) puasa, 5) haji. 2. Ibadah haji berada pada urutan kelima dan wajib bagi yang mampu. 3. Jadi jawabannya rukun Islam yang kelima." },
    { q: "Rukun haji yang menjadi penentu sah atau tidaknya ibadah haji adalah ....", options: ["Tawaf ifadah", "Sa'i", "Wukuf di Arafah", "Tahallul"], answer: 2, solution: "1. Nabi Muhammad SAW bersabda 'Al-hajju 'Arafah' yang artinya haji itu adalah wukuf di Arafah. 2. Barang siapa tidak melaksanakan wukuf di Arafah pada tanggal 9 Zulhijah, hajinya tidak sah. 3. Jadi penentu sahnya haji adalah wukuf di Arafah." },
    { q: "Sa'i adalah berlari-lari kecil antara ....", options: ["Bukit Shafa dan Bukit Marwah sebanyak tujuh kali", "Arafah dan Muzdalifah sebanyak tiga kali", "Mina dan Makkah sebanyak lima kali", "Ka'bah dan Maqam Ibrahim sebanyak tujuh kali"], answer: 0, solution: "1. Sa'i adalah salah satu rukun haji dan umrah. 2. Sa'i dilakukan dengan berjalan cepat antara Bukit Shafa dan Bukit Marwah sebanyak tujuh kali perjalanan. 3. Sa'i mengenang perjuangan Siti Hajar mencari air untuk Nabi Ismail AS." },
    { q: "Miqat adalah ....", options: ["Tempat dimulainya ihram haji atau umrah", "Bukit tempat wukuf dilaksanakan", "Sumur air zamzam di Masjidil Haram", "Pintu gerbang kota Makkah"], answer: 0, solution: "1. Sebelum memasuki rangkaian ibadah haji atau umrah, jamaah wajib berniat ihram. 2. Tempat dimulainya ihram disebut miqat, misalnya Yalamlam dan Qarnul Manazil. 3. Jadi miqat adalah batas tempat dimulainya ihram." },
    { q: "Membicarakan keburukan orang lain di belakangnya disebut ....", options: ["Ghibah", "Namimah", "Hasad", "Riya"], answer: 0, solution: "1. Akhlak tercela ada bermacam-macam, di antaranya ghibah, namimah (adu domba), hasad (dengki), dan riya (pamer). 2. Membicarakan keburukan orang lain saat ia tidak ada disebut ghibah. 3. Jadi jawabannya ghibah, bukan namimah yang artinya mengadu domba." },
    { q: "Perasaan iri dan dengki atas nikmat yang diterima orang lain disebut ....", options: ["Hasad", "Syukur", "Qanaah", "Tawadhu"], answer: 0, solution: "1. Hasad adalah akhlak tercela berupa rasa iri dan dengki, bahkan berharap nikmat orang lain hilang. 2. Lawannya adalah syukur dan qanaah, yaitu merasa cukup atas pemberian Allah. 3. Jadi jawabannya hasad." },
    { q: "Beramal saleh agar dipuji dan dilihat orang lain disebut ....", options: ["Riya", "Ikhlas", "Sabar", "Syukur"], answer: 0, solution: "1. Riya adalah beramal bukan karena Allah, melainkan agar dipuji manusia. 2. Lawannya adalah ikhlas, yaitu beramal semata-mata karena Allah SWT. 3. Riya termasuk akhlak tercela yang dapat menghapus pahala amal." },
    { q: "Lawan dari sifat amanah adalah ....", options: ["Khianat", "Jujur", "Sabar", "Ikhlas"], answer: 0, solution: "1. Amanah artinya dapat dipercaya dalam memegang titipan dan tanggung jawab. 2. Lawan dari amanah adalah khianat, yaitu menyalahgunakan kepercayaan yang diberikan. 3. Jadi jawabannya khianat." },
    { q: "Sikap merasa cukup dan rela atas pemberian Allah SWT disebut ....", options: ["Qanaah", "Tamak", "Kikir", "Sombong"], answer: 0, solution: "1. Qanaah adalah akhlak terpuji berupa sikap merasa cukup atas rezeki yang diberikan Allah. 2. Lawannya adalah tamak (rakus) dan kikir (pelit). 3. Orang yang qanaah hidupnya tenang dan jauh dari iri hati." },
    { q: "Menyombongkan diri dan merendahkan orang lain disebut ....", options: ["Takabur", "Tawadhu", "Sabar", "Pemaaf"], answer: 0, solution: "1. Takabur adalah akhlak tercela berupa sikap sombong dan merendahkan orang lain. 2. Lawannya adalah tawadhu, yaitu rendah hati. 3. Jadi jawabannya takabur." },
    { q: "Nabi Muhammad SAW lahir di kota ....", options: ["Makkah", "Madinah", "Thaif", "Yaman"], answer: 0, solution: "1. Nabi Muhammad SAW lahir pada 12 Rabiul Awal Tahun Gajah (571 M). 2. Beliau lahir di kota Makkah dari ibu bernama Aminah dan ayah bernama Abdullah. 3. Beliau hijrah ke Madinah setelah berusia 53 tahun, jadi Madinah bukan kota kelahirannya." },
    { q: "Tahun kelahiran Nabi Muhammad SAW disebut Tahun Gajah karena pada tahun itu ....", options: ["Banyak anak gajah lahir di Makkah", "Pasukan bergajah Raja Abrahah menyerang Ka'bah", "Nabi Muhammad SAW menunggang gajah", "Ka'bah dihiasi patung gajah"], answer: 1, solution: "1. Pada tahun kelahiran Nabi Muhammad SAW, Raja Abrahah dari Yaman datang menyerang Makkah. 2. Pasukannya menggunakan gajah untuk menghancurkan Ka'bah, tetapi Allah menghancurkan mereka dengan burung Ababil. 3. Peristiwa ini diabadikan dalam QS Al-Fil, sehingga tahun itu disebut Tahun Gajah." },
    { q: "Wahyu pertama turun kepada Nabi Muhammad SAW ketika beliau sedang berada di ....", options: ["Gua Hira", "Gua Tsur", "Bukit Uhud", "Masjidil Haram"], answer: 0, solution: "1. Sebelum diangkat menjadi rasul, Nabi Muhammad SAW sering menyendiri untuk bertafakur. 2. Wahyu pertama, yaitu QS Al-'Alaq ayat 1-5, turun saat beliau berada di Gua Hira pada usia 40 tahun. 3. Gua Tsur adalah tempat persembunyian saat hijrah, bukan tempat turunnya wahyu pertama." },
    { q: "Nabi Muhammad SAW hijrah dari Makkah ke ....", options: ["Madinah", "Thaif", "Habasyah", "Persia"], answer: 0, solution: "1. Karena tekanan kaum Quraisy Makkah semakin keras, Nabi Muhammad SAW diperintah Allah berhijrah. 2. Beliau hijrah dari Makkah ke Yatsrib yang kemudian bernama Madinah pada tahun 622 M. 3. Tahun hijrah ini dijadikan awal penanggalan Hijriah." },
    { q: "Kaum yang menyambut dan menolong kaum Muhajirin di Madinah disebut kaum ....", options: ["Anshar", "Quraisy", "Badui", "Muhajirin"], answer: 0, solution: "1. Kaum Muhajirin adalah kaum muslimin yang hijrah dari Makkah ke Madinah. 2. Penduduk Madinah yang menyambut, menolong, dan mempersaudarakan mereka disebut kaum Anshar yang artinya para penolong. 3. Jadi jawabannya kaum Anshar." },
    { q: "Perang pertama yang terjadi dalam sejarah Islam adalah Perang ....", options: ["Badar", "Uhud", "Khandaq", "Tabuk"], answer: 0, solution: "1. Setelah hijrah ke Madinah, kaum muslimin beberapa kali berperang mempertahankan Islam. 2. Perang pertama adalah Perang Badar yang terjadi pada 17 Ramadan tahun 2 Hijriah (624 M) dan dimenangkan kaum muslimin. 3. Perang Uhud dan Khandaq terjadi setelah Perang Badar." },
    { q: "Arti QS Al-Kafirun ayat 6 'lakum dinukum waliyadin' adalah ....", options: ["Bagimu agamamu dan bagiku agamaku", "Sesungguhnya agamaku lebih baik dari agamamu", "Tinggalkanlah agamamu dan ikutilah agamaku", "Jangan berteman dengan pemeluk agama lain"], answer: 0, solution: "1. QS Al-Kafirun menegaskan prinsip toleransi dalam beragama. 2. Ayat keenamnya berbunyi 'lakum dinukum waliyadin' yang artinya bagimu agamamu dan bagiku agamaku. 3. Ayat ini mengajarkan untuk saling menghormati keyakinan tanpa mencampuradukkan akidah." },
    { q: "Ukhuwah islamiyah artinya ....", options: ["Persaudaraan sesama muslim", "Persaudaraan sebangsa dan setanah air", "Persaudaraan karena satu suku", "Persaudaraan karena satu profesi"], answer: 0, solution: "1. Ukhuwah artinya persaudaraan. 2. Ukhuwah islamiyah adalah persaudaraan yang diikat oleh kesamaan akidah Islam, sebagaimana kaum Anshar dan Muhajirin dipersaudarakan Nabi Muhammad SAW. 3. Persaudaraan sebangsa disebut ukhuwah wathaniyah, sedangkan sesama manusia disebut ukhuwah basyariyah." },
    { q: "Rukun iman yang pertama adalah iman kepada ....", options: ["Allah SWT", "Malaikat-malaikat Allah", "Kitab-kitab Allah", "Hari akhir"], answer: 0, solution: "1. Rukun iman terdiri dari enam perkara yang diawali dengan iman kepada Allah SWT. 2. Iman kepada Allah berarti meyakini bahwa Allah itu ada, Maha Esa, dan hanya Dia yang berhak disembah. 3. Jadi rukun iman yang pertama adalah iman kepada Allah SWT." },
    { q: "Asmaul husna artinya ....", options: ["Nama-nama Allah yang baik", "Sifat-sifat para malaikat", "Nama-nama para nabi", "Gelar para sahabat Nabi"], answer: 0, solution: "1. Asmaul husna berasal dari kata asma yang berarti nama-nama dan husna yang berarti baik. 2. Jadi asmaul husna adalah nama-nama Allah SWT yang baik dan agung. 3. Jawabannya adalah nama-nama Allah yang baik." },
    { q: "Jumlah asmaul husna ada ....", options: ["66", "77", "99", "100"], answer: 2, solution: "1. Dalam hadis Nabi disebutkan bahwa Allah memiliki 99 nama. 2. Barang siapa menghafal dan memahaminya akan masuk surga. 3. Jadi jumlah asmaul husna ada 99." },
    { q: "Asmaul husna Ar-Rahman artinya Allah Maha ....", options: ["Pengasih", "Penyayang", "Pencipta", "Pemberi rezeki"], answer: 0, solution: "1. Ar-Rahman adalah salah satu dari 99 asmaul husna. 2. Ar-Rahman berarti Allah Maha Pengasih kepada seluruh makhluk-Nya tanpa terkecuali. 3. Jadi Ar-Rahman artinya Allah Maha Pengasih." },
    { q: "Asmaul husna Al-Khaliq artinya Allah Maha ....", options: ["Pencipta", "Mengetahui", "Mendengar", "Melihat"], answer: 0, solution: "1. Al-Khaliq berasal dari kata khalaqa yang berarti menciptakan. 2. Allah Maha Pencipta segala sesuatu yang ada di langit dan di bumi. 3. Jadi Al-Khaliq artinya Allah Maha Pencipta." },
    { q: "Asmaul husna As-Sami artinya Allah Maha ....", options: ["Melihat", "Mendengar", "Mengetahui", "Bijaksana"], answer: 1, solution: "1. As-Sami adalah nama Allah yang menunjukkan pendengaran-Nya. 2. Allah Maha Mendengar segala suara, baik yang keras maupun yang lirih di dalam hati. 3. Jadi As-Sami artinya Allah Maha Mendengar." },
    { q: "Asmaul husna Al-Ghaffar artinya Allah Maha ....", options: ["Pengampun", "Pemberi", "Perkasa", "Suci"], answer: 0, solution: "1. Al-Ghaffar berasal dari kata ghafara yang berarti mengampuni. 2. Allah Maha Pengampun dosa-dosa hamba-Nya yang bertobat dengan sungguh-sungguh. 3. Jadi Al-Ghaffar artinya Allah Maha Pengampun." },
    { q: "Malaikat yang bertugas menurunkan hujan dan membagi rezeki adalah ....", options: ["Jibril", "Mikail", "Israfil", "Izrail"], answer: 1, solution: "1. Jibril menyampaikan wahyu, Israfil meniup sangkakala, Izrail mencabut nyawa. 2. Malaikat yang mengatur hujan dan membagi rezeki kepada makhluk adalah Mikail. 3. Jadi jawabannya Mikail." },
    { q: "Malaikat yang bertugas meniup sangkakala pada hari kiamat adalah ....", options: ["Mikail", "Israfil", "Izrail", "Malik"], answer: 1, solution: "1. Setiap malaikat punya tugas khusus dari Allah SWT. 2. Malaikat yang akan meniup sangkakala sebagai tanda datangnya hari kiamat adalah Israfil. 3. Jadi jawabannya Israfil." },
    { q: "Malaikat yang bertugas mencabut nyawa manusia adalah ....", options: ["Jibril", "Mikail", "Izrail", "Ridwan"], answer: 2, solution: "1. Jibril menyampaikan wahyu, Mikail membagi rezeki, Ridwan menjaga surga. 2. Malaikat yang mencabut nyawa setiap makhluk yang telah tiba ajalnya adalah Izrail. 3. Jadi jawabannya Izrail." },
    { q: "Malaikat Munkar dan Nakir bertugas ....", options: ["Mencatat amal manusia", "Menanyai manusia di alam kubur", "Menjaga pintu surga", "Menjaga pintu neraka"], answer: 1, solution: "1. Malaikat Rakib dan Atid mencatat amal, Ridwan menjaga surga, Malik menjaga neraka. 2. Malaikat Munkar dan Nakir bertugas menanyai manusia di alam kubur tentang Tuhan, agama, dan nabinya. 3. Jadi tugasnya adalah menanyai manusia di alam kubur." },
    { q: "Malaikat Rakib dan Atid bertugas ....", options: ["Menyampaikan wahyu", "Mencabut nyawa", "Mencatat amal baik dan buruk manusia", "Menjaga surga dan neraka"], answer: 2, solution: "1. Menyampaikan wahyu adalah tugas Jibril, mencabut nyawa tugas Izrail, menjaga surga dan neraka tugas Ridwan dan Malik. 2. Rakib mencatat amal baik di sebelah kanan, Atid mencatat amal buruk di sebelah kiri. 3. Jadi tugasnya adalah mencatat amal baik dan buruk manusia." },
    { q: "Malaikat penjaga pintu neraka bernama ....", options: ["Malik", "Ridwan", "Jibril", "Mikail"], answer: 0, solution: "1. Ridwan menjaga surga, Jibril menyampaikan wahyu, Mikail membagi rezeki. 2. Malaikat yang menjaga pintu neraka bernama Malik. 3. Jadi jawabannya Malik." },
    { q: "Malaikat penjaga pintu surga bernama ....", options: ["Malik", "Ridwan", "Izrail", "Israfil"], answer: 1, solution: "1. Malik menjaga neraka, Izrail mencabut nyawa, Israfil meniup sangkakala. 2. Malaikat yang menjaga pintu surga bernama Ridwan. 3. Jadi jawabannya Ridwan." },
    { q: "Malaikat diciptakan Allah dari ....", options: ["Cahaya", "Api", "Tanah", "Air"], answer: 0, solution: "1. Manusia diciptakan dari tanah, jin dari api. 2. Malaikat diciptakan Allah dari cahaya (nur), sehingga mereka selalu taat dan tidak pernah bermaksiat. 3. Jadi malaikat diciptakan dari cahaya." },
    { q: "Berikut ini yang termasuk sifat malaikat adalah ....", options: ["Membutuhkan makan dan minum", "Selalu taat kepada perintah Allah", "Memiliki hawa nafsu", "Dapat berbuat dosa"], answer: 1, solution: "1. Malaikat berbeda dengan manusia dan jin: mereka tidak makan, tidak minum, dan tidak memiliki hawa nafsu. 2. Sifat utama malaikat adalah selalu taat kepada perintah Allah dan tidak pernah membangkang. 3. Jadi yang termasuk sifat malaikat adalah selalu taat kepada perintah Allah." },
    { q: "Jumlah malaikat yang wajib diketahui ada ....", options: ["8", "9", "10", "12"], answer: 2, solution: "1. Sebenarnya jumlah malaikat sangat banyak dan hanya Allah yang tahu. 2. Namun ada sepuluh malaikat yang wajib diketahui beserta tugasnya: Jibril, Mikail, Israfil, Izrail, Munkar, Nakir, Rakib, Atid, Malik, dan Ridwan. 3. Jadi jumlahnya ada 10." },
    { q: "Kitab Injil diturunkan Allah kepada Nabi ....", options: ["Musa AS", "Daud AS", "Isa AS", "Ibrahim AS"], answer: 2, solution: "1. Taurat untuk Nabi Musa AS, Zabur untuk Nabi Daud AS, Al-Quran untuk Nabi Muhammad SAW. 2. Kitab Injil diturunkan kepada Nabi Isa AS sebagai petunjuk bagi Bani Israil. 3. Jadi jawabannya Nabi Isa AS." },
    { q: "Kitab suci yang diturunkan paling akhir adalah ....", options: ["Taurat", "Zabur", "Injil", "Al-Quran"], answer: 3, solution: "1. Urutan turunnya kitab: Taurat, Zabur, Injil, lalu Al-Quran. 2. Al-Quran diturunkan kepada Nabi Muhammad SAW sebagai kitab terakhir dan penyempurna kitab-kitab sebelumnya. 3. Jadi kitab yang turun paling akhir adalah Al-Quran." },
    { q: "Selain kitab, Allah juga menurunkan suhuf kepada Nabi ....", options: ["Ibrahim AS dan Musa AS", "Daud AS dan Isa AS", "Nuh AS dan Hud AS", "Yusuf AS dan Yakub AS"], answer: 0, solution: "1. Suhuf adalah lembaran-lembaran wahyu yang lebih kecil dari kitab. 2. Suhuf diturunkan kepada Nabi Ibrahim AS dan Nabi Musa AS. 3. Jadi jawabannya Nabi Ibrahim AS dan Musa AS." },
    { q: "Iman kepada kitab-kitab Allah merupakan rukun iman yang ke-....", options: ["Kedua", "Ketiga", "Keempat", "Kelima"], answer: 1, solution: "1. Urutan rukun iman: 1) Allah, 2) malaikat, 3) kitab-kitab, 4) rasul, 5) hari akhir, 6) qadha dan qadar. 2. Iman kepada kitab-kitab Allah berada pada urutan ketiga. 3. Jadi jawabannya rukun iman yang ketiga." },
    { q: "Kitab Al-Quran diturunkan kepada Nabi ....", options: ["Isa AS", "Muhammad SAW", "Musa AS", "Daud AS"], answer: 1, solution: "1. Taurat untuk Musa AS, Zabur untuk Daud AS, Injil untuk Isa AS. 2. Al-Quran diturunkan kepada Nabi Muhammad SAW sebagai nabi dan rasul terakhir. 3. Jadi jawabannya Nabi Muhammad SAW." },
    { q: "Sifat wajib bagi rasul yang artinya benar atau jujur adalah ....", options: ["Shiddiq", "Amanah", "Tabligh", "Fathonah"], answer: 0, solution: "1. Amanah artinya dapat dipercaya, tabligh artinya menyampaikan, fathonah artinya cerdas. 2. Shiddiq artinya benar atau jujur dalam setiap perkataan dan perbuatan. 3. Jadi sifat wajib yang artinya benar atau jujur adalah shiddiq." },
    { q: "Sifat wajib bagi rasul yang artinya dapat dipercaya adalah ....", options: ["Shiddiq", "Amanah", "Tabligh", "Fathonah"], answer: 1, solution: "1. Shiddiq artinya jujur, tabligh artinya menyampaikan, fathonah artinya cerdas. 2. Amanah artinya dapat dipercaya dalam memegang dan menyampaikan amanat. 3. Jadi sifat wajib yang artinya dapat dipercaya adalah amanah." },
    { q: "Sifat wajib bagi rasul yang artinya cerdas adalah ....", options: ["Shiddiq", "Amanah", "Tabligh", "Fathonah"], answer: 3, solution: "1. Shiddiq artinya jujur, amanah artinya dapat dipercaya, tabligh artinya menyampaikan. 2. Fathonah artinya cerdas, sehingga rasul mampu berdakwah dan menjawab tantangan kaumnya dengan bijak. 3. Jadi sifat wajib yang artinya cerdas adalah fathonah." },
    { q: "Sifat mustahil bagi rasul yang artinya dusta adalah ....", options: ["Kidzib", "Khianat", "Kitman", "Baladah"], answer: 0, solution: "1. Khianat artinya tidak dapat dipercaya, kitman artinya menyembunyikan, baladah artinya bodoh. 2. Kidzib artinya dusta, lawan dari shiddiq, mustahil ada pada diri rasul. 3. Jadi sifat mustahil yang artinya dusta adalah kidzib." },
    { q: "Sifat mustahil bagi rasul yang artinya bodoh adalah ....", options: ["Kidzib", "Khianat", "Kitman", "Baladah"], answer: 3, solution: "1. Kidzib artinya dusta, khianat artinya tidak dapat dipercaya, kitman artinya menyembunyikan wahyu. 2. Baladah artinya bodoh, lawan dari fathonah, mustahil dimiliki rasul. 3. Jadi sifat mustahil yang artinya bodoh adalah baladah." },
    { q: "Sifat mustahil bagi rasul yang artinya menyembunyikan wahyu adalah ....", options: ["Kidzib", "Khianat", "Kitman", "Baladah"], answer: 2, solution: "1. Kidzib artinya dusta, khianat artinya tidak dapat dipercaya, baladah artinya bodoh. 2. Kitman artinya menyembunyikan wahyu, lawan dari tabligh, mustahil dilakukan rasul. 3. Jadi sifat mustahil yang artinya menyembunyikan wahyu adalah kitman." },
    { q: "Perbedaan utama antara nabi dan rasul adalah ....", options: ["Nabi lebih mulia daripada rasul", "Rasul diperintah menyampaikan wahyu kepada umatnya", "Nabi tidak menerima wahyu dari Allah", "Rasul tidak memiliki sifat manusiawi"], answer: 1, solution: "1. Nabi dan rasul sama-sama menerima wahyu dan sama-sama manusia pilihan yang mulia. 2. Perbedaannya: nabi menerima wahyu untuk dirinya sendiri, sedangkan rasul diperintah Allah untuk menyampaikan wahyu itu kepada umatnya. 3. Jadi perbedaan utamanya adalah rasul diperintah menyampaikan wahyu kepada umatnya." },
    { q: "Jumlah rasul yang bergelar Ulul Azmi ada ....", options: ["Tiga", "Empat", "Lima", "Enam"], answer: 2, solution: "1. Ulul Azmi adalah gelar bagi rasul yang memiliki ketabahan luar biasa dalam berdakwah. 2. Jumlahnya ada lima: Nuh, Ibrahim, Musa, Isa, dan Muhammad. 3. Jadi jumlah rasul Ulul Azmi ada lima." },
    { q: "Berikut ini yang termasuk rasul Ulul Azmi adalah ....", options: ["Nabi Yusuf AS", "Nabi Isa AS", "Nabi Daud AS", "Nabi Sulaiman AS"], answer: 1, solution: "1. Lima rasul Ulul Azmi adalah Nuh, Ibrahim, Musa, Isa, dan Muhammad SAW. 2. Dari pilihan di atas, yang termasuk Ulul Azmi adalah Nabi Isa AS. 3. Jadi jawabannya Nabi Isa AS." },
    { q: "Yaumul hisab adalah hari ....", options: ["Kebangkitan manusia", "Perhitungan amal manusia", "Penimbangan amal manusia", "Pembalasan amal manusia"], answer: 1, solution: "1. Yaumul baats adalah hari kebangkitan, yaumul mizan hari penimbangan, yaumul jaza hari pembalasan. 2. Yaumul hisab adalah hari perhitungan seluruh amal manusia selama di dunia. 3. Jadi yaumul hisab adalah hari perhitungan amal manusia." },
    { q: "Yaumul mizan adalah hari ....", options: ["Perhitungan amal", "Penimbangan amal baik dan buruk", "Pembalasan amal", "Kebangkitan manusia"], answer: 1, solution: "1. Yaumul hisab adalah hari perhitungan, yaumul jaza hari pembalasan, yaumul baats hari kebangkitan. 2. Yaumul mizan adalah hari ditimbangnya amal baik dan buruk manusia. 3. Jadi yaumul mizan adalah hari penimbangan amal baik dan buruk." },
    { q: "Yaumul jaza adalah hari ....", options: ["Kebangkitan manusia", "Perhitungan amal", "Pembalasan amal manusia", "Penimbangan amal"], answer: 2, solution: "1. Yaumul baats hari kebangkitan, yaumul hisab hari perhitungan, yaumul mizan hari penimbangan. 2. Yaumul jaza adalah hari pembalasan: yang beramal saleh mendapat surga, yang bermaksiat mendapat neraka. 3. Jadi yaumul jaza adalah hari pembalasan amal manusia." },
    { q: "Yaumul baats adalah hari ....", options: ["Dibangkitkannya manusia dari kubur", "Perhitungan seluruh amal", "Penimbangan amal baik dan buruk", "Pembalasan amal manusia"], answer: 0, solution: "1. Setelah tiupan sangkakala kedua, seluruh manusia akan dibangkitkan. 2. Hari dibangkitkannya manusia dari kubur untuk menghadap Allah disebut yaumul baats. 3. Jadi yaumul baats adalah hari dibangkitkannya manusia dari kubur." },
    { q: "Berikut ini yang termasuk tanda-tanda besar hari kiamat adalah ....", options: ["Matahari terbit dari sebelah barat", "Turunnya hujan di malam hari", "Terbitnya fajar di pagi hari", "Datangnya malam setelah siang"], answer: 0, solution: "1. Hujan, fajar, dan pergantian siang malam adalah kejadian alam biasa. 2. Tanda besar hari kiamat antara lain matahari terbit dari sebelah barat, keluarnya Dajjal, dan turunnya Nabi Isa AS. 3. Jadi yang termasuk tandanya adalah matahari terbit dari sebelah barat." },
    { q: "Iman kepada hari akhir merupakan rukun iman yang ke-....", options: ["Ketiga", "Keempat", "Kelima", "Keenam"], answer: 2, solution: "1. Urutan rukun iman: 1) Allah, 2) malaikat, 3) kitab, 4) rasul, 5) hari akhir, 6) qadha dan qadar. 2. Iman kepada hari akhir berada pada urutan kelima. 3. Jadi jawabannya rukun iman yang kelima." },
    { q: "Qadha artinya ....", options: ["Ketetapan Allah SWT", "Ukuran segala sesuatu", "Takdir yang dapat diubah", "Hasil usaha manusia"], answer: 0, solution: "1. Qadar berarti ukuran atau ketentuan, takdir muallaq dapat diubah dengan usaha. 2. Qadha adalah ketetapan Allah SWT atas segala sesuatu sejak zaman azali. 3. Jadi qadha artinya ketetapan Allah SWT." },
    { q: "Qadar artinya ....", options: ["Ketentuan atau ukuran Allah atas segala sesuatu", "Ketetapan Allah sejak zaman azali", "Usaha yang dilakukan manusia", "Doa yang dikabulkan Allah"], answer: 0, solution: "1. Qadha adalah ketetapan Allah sejak azali, sedangkan qadar adalah perwujudannya. 2. Qadar berarti ketentuan atau ukuran yang Allah tetapkan atas segala sesuatu. 3. Jadi qadar artinya ketentuan atau ukuran Allah atas segala sesuatu." },
    { q: "Takdir yang tidak dapat diubah lagi disebut takdir ....", options: ["Mubram", "Muallaq", "Qadha", "Ikhtiar"], answer: 0, solution: "1. Takdir ada dua macam berdasarkan bisa tidaknya diubah. 2. Takdir mubram adalah takdir yang pasti terjadi dan tidak dapat diubah, seperti kematian. 3. Jadi takdir yang tidak dapat diubah disebut takdir mubram." },
    { q: "Takdir yang dapat diubah dengan usaha dan doa disebut takdir ....", options: ["Mubram", "Muallaq", "Azali", "Qadha"], answer: 1, solution: "1. Takdir mubram tidak bisa diubah, misalnya kematian. 2. Takdir muallaq dapat diubah dengan ikhtiar dan doa, misalnya kepandaian dan kesuksesan. 3. Jadi takdir yang dapat diubah disebut takdir muallaq." },
    { q: "Berikut ini yang termasuk contoh takdir mubram adalah ....", options: ["Kematian", "Kepandaian", "Kekayaan", "Kesuksesan"], answer: 0, solution: "1. Kepandaian, kekayaan, dan kesuksesan bisa diusahakan sehingga termasuk takdir muallaq. 2. Kematian adalah ketetapan pasti yang tidak bisa diubah oleh siapa pun. 3. Jadi yang termasuk takdir mubram adalah kematian." },
    { q: "Thaharah artinya ....", options: ["Bersuci", "Berdoa", "Berpuasa", "Bersedekah"], answer: 0, solution: "1. Thaharah berasal dari kata thahara yang berarti bersih. 2. Dalam fikih, thaharah artinya bersuci dari hadas dan najis sebagai syarat sah ibadah. 3. Jadi thaharah artinya bersuci." },
    { q: "Contoh najis mukhaffafah adalah ....", options: ["Air kencing bayi laki-laki yang belum makan selain ASI", "Darah haid", "Air liur anjing", "Kotoran babi"], answer: 0, solution: "1. Darah haid termasuk najis mutawassithah, air liur anjing dan kotoran babi termasuk najis mughallazah. 2. Najis mukhaffafah adalah najis ringan, contohnya air kencing bayi laki-laki yang belum makan selain ASI. 3. Jadi contohnya adalah air kencing bayi laki-laki yang belum makan selain ASI." },
    { q: "Contoh najis mutawassithah adalah ....", options: ["Air kencing bayi laki-laki", "Darah dan nanah", "Air liur anjing", "Bangkai babi"], answer: 1, solution: "1. Air kencing bayi laki-laki adalah najis mukhaffafah, air liur anjing dan bangkai babi adalah najis mughallazah. 2. Najis mutawassithah adalah najis sedang, contohnya darah, nanah, dan muntah. 3. Jadi contohnya adalah darah dan nanah." },
    { q: "Contoh najis mughallazah adalah ....", options: ["Darah haid", "Air kencing bayi", "Air liur anjing dan babi", "Nanah"], answer: 2, solution: "1. Darah haid dan nanah termasuk najis mutawassithah, air kencing bayi termasuk mukhaffafah. 2. Najis mughallazah adalah najis berat, yaitu yang berasal dari anjing dan babi. 3. Jadi contohnya adalah air liur anjing dan babi." },
    { q: "Cara mensucikan najis mughallazah adalah dengan ....", options: ["Diperciki air satu kali", "Dibasuh tujuh kali dan salah satunya dengan tanah", "Dijemur di bawah matahari", "Dibiarkan hingga kering"], answer: 1, solution: "1. Najis mukhaffafah cukup diperciki air, najis mutawassithah dibasuh hingga hilang. 2. Najis mughallazah disucikan dengan membasuh tujuh kali dan salah satu basuhannya dicampur tanah atau debu. 3. Jadi caranya adalah dibasuh tujuh kali dan salah satunya dengan tanah." },
    { q: "Istinja adalah ....", options: ["Membersihkan diri dari najis setelah buang hajat", "Berwudu sebelum salat", "Mandi wajib setelah haid", "Mencuci pakaian yang kotor"], answer: 0, solution: "1. Wudu menghilangkan hadas kecil, mandi wajib menghilangkan hadas besar. 2. Istinja adalah membersihkan qubul dan dubur dari najis setelah buang air kecil atau buang air besar. 3. Jadi istinja adalah membersihkan diri dari najis setelah buang hajat." },
    { q: "Istinja dengan batu dilakukan minimal sebanyak ....", options: ["Satu kali", "Dua kali", "Tiga kali", "Lima kali"], answer: 2, solution: "1. Istinja paling utama menggunakan air yang suci. 2. Jika tidak ada air, boleh dengan tiga buah batu atau benda kesat lainnya dalam jumlah ganjil. 3. Jadi minimal tiga kali usapan batu." },
    { q: "Air yang sah digunakan untuk berwudu adalah air ....", options: ["Mutlak (suci dan mensucikan)", "Mustamal yang sudah dipakai", "Air teh dan air kopi", "Air yang tercampur sabun"], answer: 0, solution: "1. Air mustamal, air teh, dan air bercampur sabun tidak sah untuk bersuci. 2. Air yang sah adalah air mutlak, yaitu air yang suci dan mensucikan seperti air hujan, sumur, dan sungai. 3. Jadi jawabannya air mutlak." },
    { q: "Urutan anggota wudu yang benar setelah niat adalah ....", options: ["Wajah, tangan hingga siku, sebagian kepala, kaki hingga mata kaki", "Tangan, wajah, kaki, kepala", "Kepala, wajah, tangan, kaki", "Kaki, tangan, wajah, kepala"], answer: 0, solution: "1. Tertib adalah rukun wudu, sehingga urutannya tidak boleh diacak. 2. Urutan yang benar: niat, membasuh wajah, membasuh tangan hingga siku, mengusap sebagian kepala, lalu membasuh kaki hingga mata kaki. 3. Jadi urutan yang benar adalah wajah, tangan hingga siku, sebagian kepala, kaki hingga mata kaki." },
    { q: "Berikut ini yang termasuk sunah wudu adalah ....", options: ["Berkumur-kumur", "Membasuh wajah", "Mengusap sebagian kepala", "Tertib"], answer: 0, solution: "1. Membasuh wajah, mengusap sebagian kepala, dan tertib termasuk rukun wudu yang wajib. 2. Berkumur-kumur, beristinsyaq, dan mendahulukan anggota kanan termasuk sunah wudu. 3. Jadi yang termasuk sunah wudu adalah berkumur-kumur." },
    { q: "Berikut ini yang membatalkan wudu adalah ....", options: ["Kentut", "Tersenyum", "Bersin", "Menguap"], answer: 0, solution: "1. Tersenyum, bersin, dan menguap tidak membatalkan wudu. 2. Keluarnya sesuatu dari qubul atau dubur, seperti kentut, membatalkan wudu. 3. Jadi yang membatalkan wudu adalah kentut." },
    { q: "Tidur yang membatalkan wudu adalah tidur ....", options: ["Sambil duduk tegak", "Nyenyak hingga hilang kesadaran", "Sambil bersandar sebentar", "Dengan mata terpejam"], answer: 1, solution: "1. Tidur sambil duduk tegak dengan pantat menempel tidak membatalkan wudu. 2. Tidur nyenyak hingga hilang kesadaran membatalkan wudu karena dikhawatirkan keluar sesuatu tanpa disadari. 3. Jadi yang membatalkan adalah tidur nyenyak hingga hilang kesadaran." },
    { q: "Tayamum dilakukan sebagai pengganti wudu ketika ....", options: ["Malas mengambil air wudu", "Tidak ada air atau sakit yang menghalangi penggunaan air", "Sedang terburu-buru", "Airnya terasa dingin"], answer: 1, solution: "1. Malas, terburu-buru, atau air dingin bukan alasan yang dibenarkan syariat. 2. Tayamum adalah bersuci dengan debu sebagai pengganti wudu atau mandi ketika tidak ada air atau sakit yang menghalangi penggunaan air. 3. Jadi tayamum dilakukan ketika tidak ada air atau sakit yang menghalangi penggunaan air." },
    { q: "Tayamum dilakukan dengan ....", options: ["Air yang sedikit", "Debu yang suci disertai niat", "Batu kerikil saja", "Daun-daunan kering"], answer: 1, solution: "1. Tayamum adalah rukhsah (keringanan) dengan menggunakan debu. 2. Caranya: niat, lalu mengusap wajah dan kedua tangan hingga siku dengan debu yang suci. 3. Jadi tayamum dilakukan dengan debu yang suci disertai niat." },
    { q: "Mandi wajib dilakukan oleh perempuan setelah ....", options: ["Selesai haid atau nifas", "Selesai salat", "Selesai berpuasa", "Selesai membaca Al-Quran"], answer: 0, solution: "1. Salat, puasa, dan membaca Al-Quran tidak mewajibkan mandi. 2. Perempuan wajib mandi besar setelah suci dari haid atau nifas sebelum kembali beribadah. 3. Jadi mandi wajib dilakukan setelah selesai haid atau nifas." },
    { q: "Rukun mandi wajib ada dua, yaitu ....", options: ["Niat dan meratakan air ke seluruh tubuh", "Wudu dan berdoa", "Keramas dan menggosok gigi", "Berendam dan berenang"], answer: 0, solution: "1. Wudu, berdoa, dan keramas bukan rukun mandi wajib. 2. Rukun mandi wajib hanya dua: niat menghilangkan hadas besar dan meratakan air ke seluruh tubuh. 3. Jadi jawabannya niat dan meratakan air ke seluruh tubuh." },
    { q: "Hadas kecil dapat dihilangkan dengan ....", options: ["Berwudu", "Mandi wajib", "Tayamum saja", "Istinja"], answer: 0, solution: "1. Mandi wajib menghilangkan hadas besar, istinja membersihkan najis. 2. Hadas kecil seperti kentut atau buang air dihilangkan dengan berwudu. 3. Jadi hadas kecil dihilangkan dengan berwudu." },
    { q: "Menyentuh kemaluan dengan telapak tangan tanpa penghalang hukumnya ....", options: ["Membatalkan wudu", "Membatalkan puasa", "Membatalkan salat", "Tidak membatalkan apa pun"], answer: 0, solution: "1. Menyentuh kemaluan tidak membatalkan puasa atau salat secara langsung. 2. Menurut jumhur ulama, menyentuh kemaluan dengan telapak tangan tanpa penghalang membatalkan wudu. 3. Jadi hukumnya membatalkan wudu." },
    { q: "Salat fardu yang dikerjakan dalam sehari semalam berjumlah ....", options: ["Tiga waktu", "Empat waktu", "Lima waktu", "Enam waktu"], answer: 2, solution: "1. Salat fardu adalah salat yang wajib dikerjakan setiap muslim. 2. Salat fardu ada lima waktu: Subuh, Zuhur, Asar, Maghrib, dan Isya. 3. Jadi jumlahnya lima waktu." },
    { q: "Jumlah rakaat salat Zuhur adalah ....", options: ["Dua rakaat", "Tiga rakaat", "Empat rakaat", "Lima rakaat"], answer: 2, solution: "1. Subuh 2 rakaat, Maghrib 3 rakaat, Isya 4 rakaat. 2. Salat Zuhur dikerjakan sebanyak 4 rakaat pada tengah hari. 3. Jadi jumlah rakaat salat Zuhur adalah empat rakaat." },
    { q: "Jumlah rakaat salat Asar adalah ....", options: ["Dua rakaat", "Tiga rakaat", "Empat rakaat", "Lima rakaat"], answer: 2, solution: "1. Subuh 2 rakaat dan Maghrib 3 rakaat tidak boleh diqashar. 2. Salat Asar dikerjakan sebanyak 4 rakaat pada sore hari. 3. Jadi jumlah rakaat salat Asar adalah empat rakaat." },
    { q: "Waktu salat Subuh dimulai sejak ....", options: ["Terbit fajar hingga terbit matahari", "Terbenam matahari hingga hilang mega", "Tergelincir matahari hingga bayangan sama panjang", "Tengah malam hingga fajar"], answer: 0, solution: "1. Terbenam matahari adalah waktu Maghrib, tergelincir matahari adalah waktu Zuhur. 2. Waktu salat Subuh dimulai sejak terbit fajar shadiq hingga terbit matahari. 3. Jadi jawabannya terbit fajar hingga terbit matahari." },
    { q: "Syarat wajib salat adalah ....", options: ["Islam, balig, dan berakal", "Suci, menutup aurat, dan menghadap kiblat", "Berwudu, berniat, dan tertib", "Membaca Al-Fatihah dan tumaninah"], answer: 0, solution: "1. Suci, menutup aurat, dan menghadap kiblat adalah syarat sah salat. 2. Syarat wajib salat adalah Islam, balig (dewasa), dan berakal sehat. 3. Jadi jawabannya Islam, balig, dan berakal." },
    { q: "Jumlah rukun salat ada ....", options: ["Sepuluh", "Sebelas", "Tiga belas", "Lima belas"], answer: 2, solution: "1. Rukun salat meliputi niat, takbiratul ihram, berdiri, Al-Fatihah, ruku, tumaninah, iktidal, sujud, duduk di antara dua sujud, tasyahud akhir, shalawat, salam, dan tertib. 2. Jika dihitung seluruhnya berjumlah tiga belas. 3. Jadi jumlah rukun salat ada tiga belas." },
    { q: "Rukun salat yang pertama adalah ....", options: ["Takbiratul ihram", "Niat", "Membaca Al-Fatihah", "Ruku"], answer: 1, solution: "1. Takbiratul ihram, Al-Fatihah, dan ruku dikerjakan setelah salat dimulai. 2. Rukun salat yang pertama adalah niat, yaitu menyengaja mengerjakan salat di dalam hati. 3. Jadi rukun salat yang pertama adalah niat." },
    { q: "Tumaninah dalam salat artinya ....", options: ["Berhenti sejenak dengan tenang dalam setiap gerakan", "Membaca doa dengan suara keras", "Bergerak dengan cepat", "Menangis saat salat"], answer: 0, solution: "1. Tumaninah adalah salah satu rukun salat yang sering dilupakan. 2. Tumaninah artinya berhenti sejenak dengan tenang pada setiap gerakan salat seperti ruku dan sujud. 3. Jadi tumaninah artinya berhenti sejenak dengan tenang dalam setiap gerakan." },
    { q: "Berikut ini yang termasuk sunah salat adalah membaca ....", options: ["Doa iftitah", "Surah Al-Fatihah", "Tasyahud akhir", "Salam"], answer: 0, solution: "1. Al-Fatihah, tasyahud akhir, dan salam termasuk rukun salat yang wajib. 2. Doa iftitah yang dibaca setelah takbiratul ihram hukumnya sunah. 3. Jadi yang termasuk sunah salat adalah membaca doa iftitah." },
    { q: "Hukum salat berjamaah menurut jumhur ulama adalah ....", options: ["Wajib ain", "Sunah muakkad", "Makruh", "Haram"], answer: 1, solution: "1. Salat lima waktu hukumnya wajib ain bagi setiap muslim. 2. Salat berjamaah di masjid hukumnya sunah muakkad, yaitu sunah yang sangat dianjurkan. 3. Jadi hukum salat berjamaah adalah sunah muakkad." },
    { q: "Pahala salat berjamaah dibandingkan salat sendirian adalah ....", options: ["Sama saja", "Sepuluh derajat lebih utama", "Dua puluh tujuh derajat lebih utama", "Seratus derajat lebih utama"], answer: 2, solution: "1. Nabi SAW bersabda dalam hadis riwayat Bukhari dan Muslim. 2. Salat berjamaah lebih utama dua puluh tujuh derajat dibandingkan salat sendirian. 3. Jadi jawabannya dua puluh tujuh derajat lebih utama." },
    { q: "Salat Jumat merupakan pengganti salat ....", options: ["Subuh", "Zuhur", "Asar", "Maghrib"], answer: 1, solution: "1. Salat Jumat dikerjakan pada hari Jumat di waktu Zuhur. 2. Bagi laki-laki yang mengerjakan salat Jumat, ia tidak perlu lagi mengerjakan salat Zuhur karena Jumat pengganti Zuhur. 3. Jadi salat Jumat pengganti salat Zuhur." },
    { q: "Syarat sah salat Jumat adalah didahului ....", options: ["Azan dua kali", "Dua khutbah", "Salat sunah qabliyah", "Doa bersama"], answer: 1, solution: "1. Azan, salat sunah, dan doa bersama bukan syarat sah Jumat. 2. Syarat sah salat Jumat antara lain dikerjakan di waktunya, berjamaah, dan didahului dua khutbah. 3. Jadi syaratnya adalah didahului dua khutbah." },
    { q: "Jumlah takbir dalam salat jenazah adalah ....", options: ["Dua kali", "Tiga kali", "Empat kali", "Lima kali"], answer: 2, solution: "1. Salat jenazah berbeda dengan salat biasa: tanpa ruku dan sujud. 2. Salat jenazah dikerjakan dengan empat kali takbir, setiap takbir disertai bacaan tertentu. 3. Jadi jumlah takbirnya empat kali." },
    { q: "Pada takbir pertama salat jenazah dibaca ....", options: ["Surah Al-Fatihah", "Shalawat Nabi", "Doa untuk mayit", "Doa qunut"], answer: 0, solution: "1. Takbir kedua membaca shalawat, takbir ketiga membaca doa untuk mayit, takbir keempat membaca doa lalu salam. 2. Pada takbir pertama setelah takbiratul ihram dibaca surah Al-Fatihah. 3. Jadi jawabannya surah Al-Fatihah." },
    { q: "Qashar dalam salat artinya ....", options: ["Menggabungkan dua salat", "Memendekkan salat yang empat rakaat menjadi dua", "Menambah jumlah rakaat", "Mengulang salat yang tertinggal"], answer: 1, solution: "1. Menggabungkan dua salat disebut jama, menambah rakaat tidak dikenal dalam qashar. 2. Qashar artinya memendekkan salat yang empat rakaat (Zuhur, Asar, Isya) menjadi dua rakaat bagi musafir. 3. Jadi qashar artinya memendekkan salat yang empat rakaat menjadi dua." },
    { q: "Salat yang tidak boleh diqashar adalah ....", options: ["Zuhur dan Asar", "Isya dan Zuhur", "Subuh dan Maghrib", "Asar dan Isya"], answer: 2, solution: "1. Zuhur, Asar, dan Isya masing-masing empat rakaat sehingga boleh diqashar. 2. Salat Subuh (2 rakaat) dan Maghrib (3 rakaat) tidak boleh diqashar. 3. Jadi yang tidak boleh diqashar adalah Subuh dan Maghrib." },
    { q: "Jama takdim adalah ....", options: ["Menggabungkan dua salat di waktu yang pertama", "Menggabungkan dua salat di waktu yang kedua", "Memendekkan salat empat rakaat", "Mengqadha salat yang tertinggal"], answer: 0, solution: "1. Jama takhir menggabungkan di waktu kedua, qashar memendekkan rakaat. 2. Jama takdim adalah menggabungkan dua salat (misalnya Zuhur dan Asar) dan dikerjakan di waktu salat yang pertama. 3. Jadi jama takdim adalah menggabungkan dua salat di waktu yang pertama." },
    { q: "Salat sunah rawatib yang paling utama adalah ....", options: ["Qabliyah Subuh dua rakaat", "Ba'diyah Isya dua rakaat", "Qabliyah Asar empat rakaat", "Ba'diyah Maghrib dua rakaat"], answer: 0, solution: "1. Semua salat rawatib memiliki keutamaan, tetapi ada yang paling utama. 2. Nabi SAW bersabda dua rakaat qabliyah Subuh lebih baik daripada dunia dan seisinya. 3. Jadi yang paling utama adalah qabliyah Subuh dua rakaat." },
    { q: "Waktu salat Duha dimulai sejak ....", options: ["Matahari naik sekitar sepenggalah hingga sebelum Zuhur", "Tengah malam hingga fajar", "Terbenam matahari hingga Isya", "Setelah salat Subuh langsung"], answer: 0, solution: "1. Tengah malam hingga fajar adalah waktu tahajud, setelah Subuh hingga matahari naik dilarang salat sunah. 2. Waktu salat Duha dimulai sejak matahari naik sekitar sepenggalah (pukul tujuh pagi) hingga sebelum masuk waktu Zuhur. 3. Jadi jawabannya matahari naik sekitar sepenggalah hingga sebelum Zuhur." },
    { q: "Syarat mengerjakan salat tahajud adalah ....", options: ["Dilakukan setelah tidur malam", "Dilakukan sebelum tidur", "Dilakukan setelah salat Isya langsung", "Dilakukan pada siang hari"], answer: 0, solution: "1. Salat malam yang dilakukan sebelum tidur disebut qiyamullail biasa. 2. Salat tahajud adalah salat sunah malam yang dikerjakan setelah tidur malam walaupun sebentar. 3. Jadi syaratnya adalah dilakukan setelah tidur malam." },
    { q: "Salat witir dikerjakan dengan jumlah rakaat ....", options: ["Genap", "Ganjil", "Empat", "Delapan"], answer: 1, solution: "1. Witir berasal dari kata witr yang berarti ganjil. 2. Salat witir adalah salat sunah penutup malam yang dikerjakan dengan rakaat ganjil: satu, tiga, lima, dan seterusnya. 3. Jadi salat witir dikerjakan dengan jumlah rakaat ganjil." },
    { q: "Salat tarawih dikerjakan pada bulan ....", options: ["Muharram", "Rajab", "Ramadan", "Zulhijah"], answer: 2, solution: "1. Salat tarawih hanya ada pada bulan tertentu. 2. Salat tarawih adalah salat sunah malam yang dikerjakan berjamaah pada bulan Ramadan setelah salat Isya. 3. Jadi salat tarawih dikerjakan pada bulan Ramadan." },
    { q: "Sujud sahwi dilakukan karena ....", options: ["Lupa melakukan salah satu sunah abadh atau ragu jumlah rakaat", "Ingin menambah pahala", "Salatnya sudah sempurna", "Terlambat datang ke masjid"], answer: 0, solution: "1. Sujud sahwi bukan penambah pahala biasa, melainkan sujud karena lupa. 2. Sujud sahwi dilakukan dua kali sebelum salam karena lupa meninggalkan sunah abadh (tasyahud awal, qunut) atau ragu jumlah rakaat. 3. Jadi sujud sahwi dilakukan karena lupa melakukan salah satu sunah abadh atau ragu jumlah rakaat." },
    { q: "Makmum yang tertinggal satu rakaat atau lebih disebut makmum ....", options: ["Muwafiq", "Masbuk", "Munfarid", "Imam"], answer: 1, solution: "1. Makmum muwafiq mengikuti imam sejak awal, munfarid salat sendirian. 2. Makmum yang tertinggal sebagian rakaat karena terlambat disebut makmum masbuk, ia wajib menambah rakaat yang tertinggal. 3. Jadi disebut makmum masbuk." },
    { q: "Berbicara dengan sengaja saat salat hukumnya ....", options: ["Membatalkan salat", "Makruh saja", "Tidak apa-apa", "Menambah pahala"], answer: 0, solution: "1. Tersenyum kecil dan batuk karena sakit tidak membatalkan salat. 2. Berbicara dengan sengaja walau satu kata membatalkan salat menurut jumhur ulama. 3. Jadi hukumnya membatalkan salat." },
    { q: "Zakat secara bahasa artinya ....", options: ["Tumbuh, bersih, dan berkah", "Memberi dengan terpaksa", "Pajak negara", "Sedekah biasa"], answer: 0, solution: "1. Zakat berbeda dengan pajak karena merupakan ibadah yang diperintah Allah. 2. Secara bahasa zakat artinya tumbuh, bersih, suci, dan berkah. 3. Jadi zakat secara bahasa artinya tumbuh, bersih, dan berkah." },
    { q: "Nisab zakat emas adalah ....", options: ["20 dinar atau 85 gram", "200 dirham atau 595 gram", "5 wasaq atau 653 kg", "40 ekor kambing"], answer: 0, solution: "1. Perak nisabnya 200 dirham (595 gram), pertanian 5 wasaq. 2. Nisab zakat emas adalah 20 dinar atau setara 85 gram emas murni. 3. Jadi nisab zakat emas adalah 20 dinar atau 85 gram." },
    { q: "Nisab zakat perak adalah ....", options: ["85 gram", "595 gram", "653 kg", "750 kg"], answer: 1, solution: "1. Emas nisabnya 85 gram, pertanian sekitar 653 kg gabah. 2. Nisab zakat perak adalah 200 dirham atau setara 595 gram perak murni. 3. Jadi nisab zakat perak adalah 595 gram." },
    { q: "Nisab zakat hasil pertanian adalah ....", options: ["3 wasaq", "5 wasaq atau sekitar 653 kg gabah", "10 wasaq", "20 wasaq"], answer: 1, solution: "1. Hasil pertanian wajib dizakati ketika mencapai nisabnya. 2. Nisabnya adalah 5 wasaq atau sekitar 653 kg gabah kering. 3. Jadi jawabannya 5 wasaq atau sekitar 653 kg gabah." },
    { q: "Zakat hasil pertanian yang diairi dengan air hujan kadarnya ....", options: ["2,5 persen", "5 persen", "10 persen", "20 persen"], answer: 2, solution: "1. Zakat emas dan perak kadarnya 2,5 persen, pertanian beririgasi 5 persen. 2. Hasil pertanian yang diairi air hujan (tanpa biaya) zakatnya 10 persen. 3. Jadi kadarnya 10 persen." },
    { q: "Zakat hasil pertanian yang diairi dengan irigasi (membutuhkan biaya) kadarnya ....", options: ["2,5 persen", "5 persen", "10 persen", "15 persen"], answer: 1, solution: "1. Pertanian tadah hujan zakatnya 10 persen karena tanpa biaya. 2. Pertanian dengan irigasi membutuhkan biaya sehingga zakatnya lebih ringan, yaitu 5 persen. 3. Jadi kadarnya 5 persen." },
    { q: "Haul dalam zakat artinya ....", options: ["Harta telah mencapai satu tahun", "Harta telah mencapai nisab", "Harta milik penuh", "Harta lebih dari kebutuhan"], answer: 0, solution: "1. Nisab adalah batas minimal harta, milik penuh adalah kepemilikan sempurna. 2. Haul adalah masa kepemilikan harta selama satu tahun hijriah penuh. 3. Jadi haul artinya harta telah mencapai satu tahun." },
    { q: "Amil dalam delapan golongan penerima zakat artinya ....", options: ["Orang fakir", "Petugas pengelola zakat", "Orang yang berutang", "Musafir kehabisan bekal"], answer: 1, solution: "1. Fakir adalah orang yang sangat kekurangan, gharimin orang berutang, ibnu sabil musafir kehabisan bekal. 2. Amil adalah petugas yang mengurus pengumpulan dan pembagian zakat. 3. Jadi amil artinya petugas pengelola zakat." },
    { q: "Ibnu sabil dalam delapan golongan penerima zakat artinya ....", options: ["Budak yang ingin merdeka", "Musafir yang kehabisan bekal", "Orang yang baru masuk Islam", "Orang yang berjuang di jalan Allah"], answer: 1, solution: "1. Riqab adalah budak, muallaf orang baru masuk Islam, fisabilillah pejuang di jalan Allah. 2. Ibnu sabil adalah musafir yang kehabisan bekal dalam perjalanan. 3. Jadi ibnu sabil artinya musafir yang kehabisan bekal." },
    { q: "Perbedaan fakir dan miskin adalah ....", options: ["Fakir lebih membutuhkan daripada miskin", "Miskin lebih membutuhkan daripada fakir", "Keduanya sama saja", "Fakir adalah orang kaya"], answer: 0, solution: "1. Fakir dan miskin sama-sama berhak menerima zakat tetapi tingkatannya berbeda. 2. Fakir adalah orang yang sangat kekurangan dan hampir tidak punya apa-apa, sehingga lebih membutuhkan daripada miskin yang masih punya sedikit penghasilan. 3. Jadi fakir lebih membutuhkan daripada miskin." },
    { q: "Waktu utama membayar zakat fitrah adalah ....", options: ["Awal bulan Ramadan", "Sebelum salat Idulfitri", "Setelah salat Idulfitri", "Akhir bulan Syawal"], answer: 1, solution: "1. Zakat fitrah wajib sejak awal Ramadan hingga sebelum salat Id. 2. Waktu yang paling utama adalah sebelum salat Idulfitri agar dapat segera dimanfaatkan fakir miskin. 3. Jadi waktu utamanya adalah sebelum salat Idulfitri." },
    { q: "Zakat fitrah wajib atas ....", options: ["Setiap muslim laki-laki dan perempuan, kecil maupun dewasa", "Hanya laki-laki dewasa", "Hanya orang kaya", "Hanya orang yang berpuasa penuh"], answer: 0, solution: "1. Zakat fitrah berbeda dengan zakat mal yang hanya wajib bagi pemilik harta mencapai nisab. 2. Zakat fitrah wajib atas setiap muslim, laki-laki maupun perempuan, kecil maupun dewasa, yang memiliki kelebihan makanan di hari raya. 3. Jadi wajib atas setiap muslim laki-laki dan perempuan, kecil maupun dewasa." },
    { q: "Orang yang berhak menerima zakat disebut ....", options: ["Muzakki", "Mustahik", "Amil", "Wakil"], answer: 1, solution: "1. Muzakki adalah orang yang membayar zakat, amil adalah petugas zakat. 2. Mustahik adalah orang yang berhak menerima zakat, jumlahnya delapan golongan. 3. Jadi disebut mustahik." },
    { q: "Hikmah membayar zakat bagi pemberi adalah ....", options: ["Hartanya berkurang banyak", "Membersihkan harta dan menumbuhkan kepedulian sosial", "Menjadi miskin", "Dipuji orang"], answer: 1, solution: "1. Zakat tidak membuat miskin, justru Allah menjanjikan keberkahan. 2. Hikmah zakat bagi muzakki adalah membersihkan harta dari hak orang lain dan menumbuhkan kepedulian sosial. 3. Jadi hikmahnya adalah membersihkan harta dan menumbuhkan kepedulian sosial." },
    { q: "Puasa (shaum) secara bahasa artinya ....", options: ["Menahan diri", "Tidak makan saja", "Tidur seharian", "Beribadah malam"], answer: 0, solution: "1. Shaum berasal dari kata shama yang berarti menahan. 2. Secara bahasa puasa artinya menahan diri dari segala yang membatalkan, dari terbit fajar hingga terbenam matahari. 3. Jadi puasa secara bahasa artinya menahan diri." },
    { q: "Syarat wajib puasa adalah ....", options: ["Islam, balig, berakal, dan mampu", "Kaya, sehat, dan merdeka", "Laki-laki dan dewasa", "Tinggal di kota"], answer: 0, solution: "1. Puasa wajib atas setiap muslim yang memenuhi syarat. 2. Syarat wajib puasa adalah Islam, balig, berakal sehat, dan mampu melaksanakannya. 3. Jadi jawabannya Islam, balig, berakal, dan mampu." },
    { q: "Rukun puasa ada dua, yaitu ....", options: ["Niat dan menahan diri dari yang membatalkan", "Sahur dan berbuka", "Tarawih dan witir", "Membaca Al-Quran dan berzikir"], answer: 0, solution: "1. Sahur, berbuka, tarawih, dan membaca Al-Quran adalah sunah atau pelengkap. 2. Rukun puasa hanya dua: niat dan menahan diri dari segala yang membatalkan puasa. 3. Jadi rukunnya adalah niat dan menahan diri dari yang membatalkan." },
    { q: "Makan dan minum dengan sengaja saat berpuasa hukumnya ....", options: ["Membatalkan puasa", "Makruh", "Tidak apa-apa", "Menambah pahala"], answer: 0, solution: "1. Berkumur saat wudu dan mencium bau masakan tidak membatalkan puasa. 2. Makan dan minum dengan sengaja jelas membatalkan puasa dan wajib diqadha. 3. Jadi hukumnya membatalkan puasa." },
    { q: "Muntah dengan sengaja saat berpuasa hukumnya ....", options: ["Membatalkan puasa", "Tidak membatalkan puasa", "Makruh", "Sunah"], answer: 0, solution: "1. Muntah yang tidak disengaja tidak membatalkan puasa. 2. Muntah yang disengaja, misalnya dengan memasukkan jari ke tenggorokan, membatalkan puasa. 3. Jadi muntah dengan sengaja membatalkan puasa." },
    { q: "Orang yang makan karena lupa saat berpuasa maka puasanya ....", options: ["Batal dan wajib qadha", "Tetap sah dan diteruskan", "Batal tetapi tidak qadha", "Harus membayar fidyah"], answer: 1, solution: "1. Nabi SAW bersabda bahwa orang yang lupa makan saat puasa itu diberi makan oleh Allah. 2. Makan karena lupa tidak membatalkan puasa, maka puasanya tetap sah dan diteruskan. 3. Jadi puasanya tetap sah dan diteruskan." },
    { q: "Orang tua renta yang tidak mampu berpuasa wajib membayar ....", options: ["Qadha", "Fidyah", "Kafarat", "Denda"], answer: 1, solution: "1. Qadha adalah mengganti puasa di hari lain, wajib bagi yang masih mampu. 2. Orang tua renta dan orang sakit menahun yang tidak mampu berpuasa dan tidak mungkin mengqadha wajib membayar fidyah, yaitu memberi makan fakir miskin. 3. Jadi wajib membayar fidyah." },
    { q: "Musafir yang tidak berpuasa di bulan Ramadan wajib ....", options: ["Membayar fidyah", "Mengqadha di hari lain", "Membayar kafarat", "Tidak wajib apa-apa"], answer: 1, solution: "1. Musafir dan orang sakit diberi keringanan untuk tidak berpuasa. 2. Sebagai gantinya mereka wajib mengqadha (mengganti) puasa di hari lain di luar Ramadan. 3. Jadi wajib mengqadha di hari lain." },
    { q: "Puasa sunah yang dikerjakan setiap pekan adalah puasa ....", options: ["Senin dan Kamis", "Ayyamul bidh", "Asyura", "Arafah"], answer: 0, solution: "1. Ayyamul bidh setiap bulan, Asyura setahun sekali, Arafah setahun sekali. 2. Puasa sunah Senin dan Kamis dikerjakan setiap pekan karena pada dua hari itu amal diangkat. 3. Jadi puasa sunah setiap pekan adalah puasa Senin dan Kamis." },
    { q: "Puasa Ayyamul Bidh dikerjakan pada tanggal ....", options: ["1, 2, 3 Hijriah", "13, 14, 15 Hijriah", "27, 28, 29 Hijriah", "10 Muharram saja"], answer: 1, solution: "1. Ayyamul bidh artinya hari-hari putih, yaitu saat bulan purnama. 2. Puasa sunah Ayyamul Bidh dikerjakan pada tanggal 13, 14, dan 15 setiap bulan Hijriah. 3. Jadi jawabannya tanggal 13, 14, 15 Hijriah." },
    { q: "Puasa Asyura dikerjakan pada tanggal ....", options: ["1 Muharram", "10 Muharram", "27 Rajab", "12 Rabiul Awal"], answer: 1, solution: "1. 1 Muharram adalah tahun baru Hijriah, 27 Rajab peringatan Isra Mikraj. 2. Puasa Asyura adalah puasa sunah pada tanggal 10 Muharram yang dapat menghapus dosa setahun lalu. 3. Jadi puasa Asyura pada tanggal 10 Muharram." },
    { q: "Puasa Arafah dikerjakan pada tanggal ....", options: ["9 Zulhijah", "10 Zulhijah", "1 Zulhijah", "8 Zulhijah"], answer: 0, solution: "1. 10 Zulhijah adalah Iduladha, 8 Zulhijah adalah hari tarwiyah. 2. Puasa Arafah dikerjakan pada tanggal 9 Zulhijah, bersamaan dengan wukuf jamaah haji di Arafah. 3. Jadi puasa Arafah pada tanggal 9 Zulhijah." },
    { q: "Lailatul qadar adalah malam yang ....", options: ["Lebih baik dari seribu bulan", "Penuh dengan hujan", "Sama dengan malam biasa", "Hanya ada di Mekah"], answer: 0, solution: "1. Lailatul qadar adalah malam kemuliaan yang turun pada bulan Ramadan. 2. Allah berfirman bahwa lailatul qadar lebih baik dari seribu bulan. 3. Jadi lailatul qadar adalah malam yang lebih baik dari seribu bulan." },
    { q: "Tujuan utama ibadah puasa menurut QS Al-Baqarah ayat 183 adalah agar menjadi ....", options: ["Kaya raya", "Orang yang bertakwa", "Terkenal", "Kuat fisik"], answer: 1, solution: "1. QS Al-Baqarah ayat 183 memerintahkan puasa seperti umat terdahulu. 2. Tujuan akhirnya disebutkan: laallakum tattaqun, agar kamu menjadi orang-orang yang bertakwa. 3. Jadi tujuannya agar menjadi orang yang bertakwa." },
    { q: "Haji secara bahasa artinya ....", options: ["Menyengaja atau berkunjung", "Berkeliling Kakbah", "Berlari-lari kecil", "Bercukur rambut"], answer: 0, solution: "1. Berkeliling Kakbah adalah tawaf, berlari kecil adalah sai, bercukur adalah tahallul. 2. Haji secara bahasa artinya menyengaja atau berkunjung ke Baitullah. 3. Jadi haji secara bahasa artinya menyengaja atau berkunjung." },
    { q: "Rukun haji yang pertama adalah ....", options: ["Ihram", "Wukuf", "Tawaf", "Sai"], answer: 0, solution: "1. Wukuf, tawaf, dan sai dikerjakan setelah memasuki ihram. 2. Rukun haji diawali dengan ihram, yaitu niat memasuki ibadah haji disertai larangan-larangannya. 3. Jadi rukun haji yang pertama adalah ihram." },
    { q: "Wukuf dilaksanakan di ....", options: ["Muzdalifah", "Mina", "Arafah", "Mekah"], answer: 2, solution: "1. Muzdalifah tempat mabit, Mina tempat melontar jumrah. 2. Wukuf adalah berdiam diri di Padang Arafah pada tanggal 9 Zulhijah. 3. Jadi wukuf dilaksanakan di Arafah." },
    { q: "Tawaf adalah mengelilingi Kakbah sebanyak ....", options: ["Tiga kali", "Lima kali", "Tujuh kali", "Sepuluh kali"], answer: 2, solution: "1. Tawaf adalah salah satu rukun haji. 2. Tawaf dilakukan dengan mengelilingi Kakbah sebanyak tujuh kali putaran. 3. Jadi tawaf adalah mengelilingi Kakbah sebanyak tujuh kali." },
    { q: "Jumlah putaran sai antara Bukit Shafa dan Marwah adalah ....", options: ["Tiga kali", "Lima kali", "Tujuh kali", "Sembilan kali"], answer: 2, solution: "1. Sai adalah rukun haji berupa berlari-lari kecil. 2. Sai dilakukan antara Bukit Shafa dan Bukit Marwah sebanyak tujuh kali putaran. 3. Jadi jumlah putarannya tujuh kali." },
    { q: "Tahallul artinya ....", options: ["Bercukur atau memotong rambut", "Berkeliling Kakbah", "Berdiam di Arafah", "Melontar jumrah"], answer: 0, solution: "1. Berkeliling Kakbah adalah tawaf, berdiam di Arafah adalah wukuf, melontar adalah jumrah. 2. Tahallul artinya bercukur atau memotong rambut sebagai tanda selesai dari sebagian larangan ihram. 3. Jadi tahallul artinya bercukur atau memotong rambut." },
    { q: "Berikut ini yang termasuk larangan ihram bagi laki-laki adalah ....", options: ["Memakai pakaian berjahit", "Memakai kain ihram", "Berniat haji", "Membaca talbiyah"], answer: 0, solution: "1. Memakai kain ihram, berniat, dan membaca talbiyah adalah hal yang diperintah saat ihram. 2. Larangan ihram bagi laki-laki antara lain memakai pakaian berjahit dan menutup kepala. 3. Jadi yang termasuk larangan adalah memakai pakaian berjahit." },
    { q: "Memakai wangi-wangian saat ihram hukumnya ....", options: ["Dilarang", "Dianjurkan", "Wajib", "Makruh"], answer: 0, solution: "1. Sebelum ihram justru disunahkan memakai wangi-wangian. 2. Setelah memasuki ihram, memakai wangi-wangian termasuk larangan ihram yang wajib dijauhi. 3. Jadi hukumnya dilarang." },
    { q: "Mabit di Muzdalifah termasuk ....", options: ["Rukun haji", "Wajib haji", "Sunah haji", "Larangan haji"], answer: 1, solution: "1. Rukun haji ada enam: ihram, wukuf, tawaf, sai, tahallul, tertib. 2. Mabit (bermalam) di Muzdalifah termasuk wajib haji; jika ditinggalkan wajib membayar dam. 3. Jadi mabit di Muzdalifah termasuk wajib haji." },
    { q: "Dam dalam ibadah haji artinya ....", options: ["Denda karena melanggar wajib haji", "Hadiah untuk panitia", "Ongkos perjalanan", "Uang saku"], answer: 0, solution: "1. Dam berasal dari kata damm yang berarti darah (menyembelih hewan). 2. Dam adalah denda berupa menyembelih hewan karena meninggalkan wajib haji atau melanggar larangan ihram. 3. Jadi dam artinya denda karena melanggar wajib haji." },
    { q: "Syarat wajib haji adalah ....", options: ["Islam, balig, berakal, merdeka, dan mampu", "Kaya raya dan punya jabatan", "Laki-laki dan sudah menikah", "Tinggal di Arab Saudi"], answer: 0, solution: "1. Haji adalah rukun Islam kelima yang wajib sekali seumur hidup. 2. Syarat wajib haji adalah Islam, balig, berakal, merdeka, dan istithaah (mampu lahir batin). 3. Jadi jawabannya Islam, balig, berakal, merdeka, dan mampu." },
    { q: "Melontar jumrah dilakukan di ....", options: ["Arafah", "Muzdalifah", "Mina", "Mekah"], answer: 2, solution: "1. Arafah tempat wukuf, Muzdalifah tempat mabit. 2. Melontar tiga jumrah (ula, wustha, aqabah) dilakukan di Mina pada hari-hari tasyrik. 3. Jadi melontar jumrah dilakukan di Mina." },
    { q: "Akhlak secara bahasa artinya ....", options: ["Budi pekerti atau tabiat", "Pakaian yang bagus", "Rumah yang mewah", "Makanan yang lezat"], answer: 0, solution: "1. Akhlak berasal dari kata khuluq yang berarti tabiat atau kebiasaan. 2. Dalam istilah, akhlak adalah budi pekerti yang melekat pada diri seseorang. 3. Jadi akhlak secara bahasa artinya budi pekerti atau tabiat." },
    { q: "Jujur dalam perkataan dan perbuatan disebut ....", options: ["Shiddiq", "Amanah", "Tawadhu", "Sabar"], answer: 0, solution: "1. Amanah artinya dapat dipercaya, tawadhu artinya rendah hati, sabar artinya tabah. 2. Jujur atau benar dalam perkataan dan perbuatan disebut shiddiq. 3. Jadi jawabannya shiddiq." },
    { q: "Amanah artinya ....", options: ["Dapat dipercaya", "Rendah hati", "Pemaaf", "Dermawan"], answer: 0, solution: "1. Rendah hati adalah tawadhu, pemaaf adalah afwu, dermawan adalah jud. 2. Amanah artinya dapat dipercaya dalam menjaga titipan dan janji. 3. Jadi amanah artinya dapat dipercaya." },
    { q: "Tawadhu artinya ....", options: ["Rendah hati", "Sombong", "Pemarah", "Pendendam"], answer: 0, solution: "1. Sombong adalah takabur, lawan dari tawadhu. 2. Tawadhu artinya rendah hati, tidak menyombongkan diri di hadapan orang lain. 3. Jadi tawadhu artinya rendah hati." },
    { q: "Syukur kepada Allah dapat diwujudkan dengan ....", options: ["Hati, lisan, dan perbuatan", "Hanya ucapan saja", "Hanya dalam hati", "Menunggu nikmat besar"], answer: 0, solution: "1. Syukur bukan sekadar ucapan tanpa bukti. 2. Syukur diwujudkan dengan tiga cara: meyakini dalam hati, mengucap tahmid dengan lisan, dan menggunakan nikmat untuk ketaatan. 3. Jadi syukur diwujudkan dengan hati, lisan, dan perbuatan." },
    { q: "Sabar dalam menjauhi maksiat disebut sabar ....", options: ["Dalam ketaatan", "Dalam menjauhi maksiat", "Dalam menghadapi musibah", "Dalam mencari rezeki"], answer: 1, solution: "1. Sabar ada tiga macam menurut ulama. 2. Sabar dalam menjauhi maksiat adalah menahan diri dari perbuatan dosa padahal ada kesempatan. 3. Jadi disebut sabar dalam menjauhi maksiat." },
    { q: "Ikhlas dalam beramal artinya ....", options: ["Beramal hanya karena Allah SWT", "Beramal agar dipuji orang", "Beramal agar terkenal", "Beramal karena terpaksa"], answer: 0, solution: "1. Beramal agar dipuji adalah riya, beramal agar terkenal adalah sumah. 2. Ikhlas artinya beramal hanya karena Allah SWT tanpa mengharap pujian manusia. 3. Jadi ikhlas artinya beramal hanya karena Allah SWT." },
    { q: "Sikap mudah memaafkan kesalahan orang lain disebut ....", options: ["Afwu", "Hasad", "Ghibah", "Namimah"], answer: 0, solution: "1. Hasad adalah dengki, ghibah adalah menggunjing, namimah adalah adu domba. 2. Afwu artinya memaafkan, yaitu lapang dada atas kesalahan orang lain. 3. Jadi sikap mudah memaafkan disebut afwu." },
    { q: "Husnuzan artinya ....", options: ["Berbaik sangka", "Berburuk sangka", "Mudah marah", "Suka mengeluh"], answer: 0, solution: "1. Berburuk sangka adalah suuzan, lawan dari husnuzan. 2. Husnuzan artinya berbaik sangka kepada Allah dan kepada sesama manusia. 3. Jadi husnuzan artinya berbaik sangka." },
    { q: "Tolong-menolong dalam kebaikan diperintahkan dalam QS ....", options: ["Al-Maidah ayat 2", "Al-Kafirun ayat 6", "Al-Hujurat ayat 13", "Al-Ikhlas ayat 1"], answer: 0, solution: "1. Al-Kafirun ayat 6 tentang toleransi beragama, Al-Hujurat ayat 13 tentang persaudaraan manusia. 2. Perintah tolong-menolong dalam kebaikan dan takwa terdapat dalam QS Al-Maidah ayat 2. 3. Jadi jawabannya QS Al-Maidah ayat 2." },
    { q: "Namimah artinya ....", options: ["Adu domba", "Menggunjing", "Berdusta", "Mencuri"], answer: 0, solution: "1. Menggunjing adalah ghibah, berdusta adalah kidzib. 2. Namimah adalah adu domba, yaitu menyebarkan perkataan untuk memecah belah persaudaraan. 3. Jadi namimah artinya adu domba." },
    { q: "Israf artinya ....", options: ["Berlebih-lebihan", "Hemat", "Sederhana", "Rajin"], answer: 0, solution: "1. Hemat dan sederhana adalah lawan dari israf. 2. Israf artinya berlebih-lebihan dalam menggunakan harta atau nikmat, dan Allah tidak menyukai orang yang berlebih-lebihan. 3. Jadi israf artinya berlebih-lebihan." },
    { q: "Zalim artinya ....", options: ["Berbuat aniaya", "Berbuat adil", "Berbuat baik", "Berbuat jujur"], answer: 0, solution: "1. Adil, baik, dan jujur adalah akhlak terpuji. 2. Zalim artinya berbuat aniaya, yaitu menempatkan sesuatu tidak pada tempatnya atau merugikan orang lain. 3. Jadi zalim artinya berbuat aniaya." },
    { q: "Fitnah lebih kejam daripada pembunuhan dijelaskan dalam QS ....", options: ["Al-Baqarah ayat 191", "Al-Maidah ayat 2", "Al-Hujurat ayat 12", "An-Nisa ayat 36"], answer: 0, solution: "1. Al-Maidah ayat 2 tentang tolong-menolong, Al-Hujurat ayat 12 tentang ghibah. 2. Dalam QS Al-Baqarah ayat 191 Allah berfirman bahwa fitnah itu lebih kejam daripada pembunuhan. 3. Jadi jawabannya QS Al-Baqarah ayat 191." },
    { q: "Berbakti kepada kedua orang tua disebut ....", options: ["Birrul walidain", "Ukhuwah islamiyah", "Tasamuh", "Tabayyun"], answer: 0, solution: "1. Ukhuwah islamiyah adalah persaudaraan seiman, tasamuh adalah toleransi, tabayyun adalah meneliti berita. 2. Berbakti dan berbuat baik kepada kedua orang tua disebut birrul walidain. 3. Jadi jawabannya birrul walidain." },
    { q: "Tabayyun artinya ....", options: ["Meneliti kebenaran suatu berita", "Menyebarkan berita cepat", "Menyembunyikan berita", "Membuat berita bohong"], answer: 0, solution: "1. Menyebarkan berita tanpa diteliti dapat menimbulkan fitnah. 2. Tabayyun artinya meneliti dan memeriksa kebenaran suatu berita sebelum dipercaya atau disebarkan. 3. Jadi tabayyun artinya meneliti kebenaran suatu berita." },
    { q: "Ujub artinya ....", options: ["Bangga diri secara berlebihan", "Rendah hati", "Pemaaf", "Dermawan"], answer: 0, solution: "1. Rendah hati adalah tawadhu, lawan dari ujub. 2. Ujub artinya bangga diri secara berlebihan atas kelebihan yang dimiliki hingga meremehkan orang lain. 3. Jadi ujub artinya bangga diri secara berlebihan." },
    { q: "Lawan dari husnuzan adalah ....", options: ["Suuzan", "Tawadhu", "Sabar", "Ikhlas"], answer: 0, solution: "1. Tawadhu, sabar, dan ikhlas adalah akhlak terpuji yang sejalan dengan husnuzan. 2. Lawan dari husnuzan (berbaik sangka) adalah suuzan (berburuk sangka). 3. Jadi lawannya adalah suuzan." },
    { q: "Akhlak terpuji kepada guru adalah ....", options: ["Menghormati dan mendengarkan nasihatnya", "Membantah setiap perkataannya", "Mengabaikan pelajarannya", "Mengejeknya di belakang"], answer: 0, solution: "1. Membantah, mengabaikan, dan mengejek guru termasuk akhlak tercela. 2. Akhlak terpuji kepada guru adalah menghormatinya, mendengarkan nasihatnya, dan mendoakannya. 3. Jadi jawabannya menghormati dan mendengarkan nasihatnya." },
    { q: "Akhlak terpuji kepada tetangga adalah ....", options: ["Saling membantu dan tidak mengganggunya", "Acuh tak acuh", "Suka menggosipinya", "Iri atas keberhasilannya"], answer: 0, solution: "1. Nabi SAW sangat menekankan hak tetangga hingga Jibril berwasiat tentangnya. 2. Akhlak terpuji kepada tetangga adalah saling membantu, berbagi, dan tidak mengganggunya. 3. Jadi jawabannya saling membantu dan tidak mengganggunya." },
    { q: "Nabi Muhammad SAW lahir pada tanggal ....", options: ["12 Rabiul Awal", "17 Ramadan", "27 Rajab", "1 Muharram"], answer: 0, solution: "1. 17 Ramadan adalah Nuzulul Quran, 27 Rajab peringatan Isra Mikraj, 1 Muharram tahun baru Hijriah. 2. Nabi Muhammad SAW lahir pada 12 Rabiul Awal Tahun Gajah atau 571 Masehi. 3. Jadi jawabannya 12 Rabiul Awal." },
    { q: "Ayah Nabi Muhammad SAW bernama ....", options: ["Abdullah", "Abdul Muthalib", "Abu Thalib", "Hamzah"], answer: 0, solution: "1. Abdul Muthalib adalah kakek Nabi, Abu Thalib adalah pamannya, Hamzah juga pamannya. 2. Ayah Nabi Muhammad SAW bernama Abdullah yang wafat saat Nabi masih dalam kandungan. 3. Jadi jawabannya Abdullah." },
    { q: "Ibu Nabi Muhammad SAW bernama ....", options: ["Khadijah", "Aminah", "Halimah", "Fatimah"], answer: 1, solution: "1. Khadijah adalah istri Nabi, Halimah adalah ibu susuannya, Fatimah adalah putrinya. 2. Ibu kandung Nabi Muhammad SAW bernama Aminah binti Wahb. 3. Jadi jawabannya Aminah." },
    { q: "Istri pertama Nabi Muhammad SAW bernama ....", options: ["Aisyah", "Khadijah", "Hafsah", "Zainab"], answer: 1, solution: "1. Aisyah, Hafsah, dan Zainab adalah istri-istri Nabi setelah Khadijah wafat. 2. Istri pertama Nabi adalah Khadijah binti Khuwailid yang setia mendampingi dakwah beliau. 3. Jadi jawabannya Khadijah." },
    { q: "Wahyu pertama yang turun adalah QS Al-Alaq ayat ....", options: ["1-5", "1-7", "1-3", "1-10"], answer: 0, solution: "1. Wahyu pertama turun di Gua Hira saat Nabi berusia 40 tahun. 2. Wahyu pertama adalah QS Al-Alaq ayat 1 sampai 5 yang diawali perintah iqra. 3. Jadi jawabannya QS Al-Alaq ayat 1-5." },
    { q: "Peristiwa Isra Mikraj terjadi pada malam hari dari ....", options: ["Masjidil Haram ke Masjidil Aqsa lalu ke Sidratul Muntaha", "Mekah ke Madinah", "Gua Hira ke rumah Khadijah", "Madinah ke Mekah"], answer: 0, solution: "1. Mekah ke Madinah adalah peristiwa hijrah. 2. Isra adalah perjalanan malam dari Masjidil Haram ke Masjidil Aqsa, Mikraj adalah naik ke Sidratul Muntaha. 3. Jadi jawabannya Masjidil Haram ke Masjidil Aqsa lalu ke Sidratul Muntaha." },
    { q: "Kendaraan yang digunakan Nabi saat Isra Mikraj bernama ....", options: ["Buraq", "Unta", "Kuda", "Gajah"], answer: 0, solution: "1. Perjalanan Isra Mikraj adalah mukjizat dengan kendaraan khusus. 2. Nabi SAW melakukan Isra Mikraj dengan menunggang Buraq, hewan putih secepat kilat. 3. Jadi kendaraan itu bernama Buraq." },
    { q: "Nabi Muhammad SAW hijrah ke Madinah pada tahun ....", options: ["571 M", "622 M", "632 M", "610 M"], answer: 1, solution: "1. 571 M adalah tahun kelahiran Nabi, 610 M awal kenabian, 632 M tahun wafat Nabi. 2. Hijrah Nabi dari Mekah ke Madinah terjadi pada tahun 622 M dan menjadi awal kalender Hijriah. 3. Jadi jawabannya tahun 622 M." },
    { q: "Sahabat yang menemani Nabi hijrah ke Madinah adalah ....", options: ["Umar bin Khattab", "Abu Bakar Ash-Shiddiq", "Ali bin Abi Thalib", "Utsman bin Affan"], answer: 1, solution: "1. Ali ditugaskan tidur di tempat tidur Nabi untuk mengelabui kaum kafir. 2. Sahabat yang menemani Nabi dalam perjalanan hijrah hingga bersembunyi di Gua Tsur adalah Abu Bakar Ash-Shiddiq. 3. Jadi jawabannya Abu Bakar Ash-Shiddiq." },
    { q: "Gua tempat Nabi dan Abu Bakar bersembunyi saat hijrah adalah Gua ....", options: ["Hira", "Tsur", "Kahfi", "Uhud"], answer: 1, solution: "1. Gua Hira tempat wahyu pertama turun, Gua Kahfi kisah Ashabul Kahfi. 2. Saat hijrah, Nabi dan Abu Bakar bersembunyi dari kejaran kaum kafir di Gua Tsur selama tiga hari. 3. Jadi jawabannya Gua Tsur." },
    { q: "Masjid pertama yang dibangun Nabi di Madinah adalah Masjid ....", options: ["Nabawi", "Quba", "Qiblatain", "Jumat"], answer: 1, solution: "1. Masjid Nabawi dibangun setelah Nabi tiba di pusat Kota Madinah. 2. Masjid pertama yang dibangun Nabi setibanya di Madinah adalah Masjid Quba. 3. Jadi jawabannya Masjid Quba." },
    { q: "Piagam Madinah berisi tentang ....", options: ["Persaudaraan dan aturan hidup bersama antarumat beragama", "Perintah perang", "Larangan berdagang", "Pembagian harta rampasan"], answer: 0, solution: "1. Piagam Madinah adalah konstitusi tertulis pertama yang dibuat Nabi. 2. Isinya mengatur persaudaraan kaum muslimin serta hak dan kewajiban hidup bersama antarumat beragama di Madinah. 3. Jadi isinya tentang persaudaraan dan aturan hidup bersama antarumat beragama." },
    { q: "Perang Uhud terjadi pada tahun ....", options: ["2 Hijriah", "3 Hijriah", "5 Hijriah", "8 Hijriah"], answer: 1, solution: "1. Perang Badar 2 H, Perang Khandaq 5 H, Fathu Mekah 8 H. 2. Perang Uhud terjadi pada tahun 3 Hijriah dan kaum muslimin kalah karena pasukan pemanah meninggalkan posnya. 3. Jadi jawabannya 3 Hijriah." },
    { q: "Perang Khandaq disebut juga Perang ....", options: ["Badar", "Uhud", "Parit", "Tabuk"], answer: 2, solution: "1. Perang Khandaq terjadi pada tahun 5 Hijriah. 2. Disebut Perang Parit karena kaum muslimin menggali parit atas usul Salman Al-Farisi untuk menghadang pasukan gabungan. 3. Jadi disebut juga Perang Parit." },
    { q: "Fathu Mekah terjadi pada tahun ....", options: ["2 Hijriah", "5 Hijriah", "8 Hijriah", "10 Hijriah"], answer: 2, solution: "1. Badar 2 H, Khandaq 5 H, Haji Wada 10 H. 2. Fathu Mekah (penaklukan Kota Mekah) terjadi pada tahun 8 Hijriah hampir tanpa pertumpahan darah. 3. Jadi jawabannya 8 Hijriah." },
    { q: "Khalifah pertama setelah Nabi wafat adalah ....", options: ["Umar bin Khattab", "Abu Bakar Ash-Shiddiq", "Utsman bin Affan", "Ali bin Abi Thalib"], answer: 1, solution: "1. Umar khalifah kedua, Utsman ketiga, Ali keempat. 2. Khalifah pertama yang menggantikan Nabi adalah Abu Bakar Ash-Shiddiq dengan masa pemerintahan dua tahun. 3. Jadi jawabannya Abu Bakar Ash-Shiddiq." },
    { q: "Khalifah Umar bin Khattab memerintah selama ....", options: ["2 tahun", "5 tahun", "10 tahun", "12 tahun"], answer: 2, solution: "1. Abu Bakar memerintah 2 tahun, Utsman 12 tahun, Ali 5 tahun. 2. Umar bin Khattab bergelar Al-Faruq memerintah selama 10 tahun (634-644 M). 3. Jadi jawabannya 10 tahun." },
    { q: "Khalifah yang dijuluki Dzun Nurain adalah ....", options: ["Abu Bakar", "Umar bin Khattab", "Utsman bin Affan", "Ali bin Abi Thalib"], answer: 2, solution: "1. Abu Bakar dijuluki Ash-Shiddiq, Umar dijuluki Al-Faruq. 2. Utsman bin Affan dijuluki Dzun Nurain (pemilik dua cahaya) karena menikahi dua putri Nabi. 3. Jadi jawabannya Utsman bin Affan." },
    { q: "QS Al-Hujurat ayat 13 menjelaskan bahwa manusia diciptakan berbangsa-bangsa agar ....", options: ["Saling bermusuhan", "Saling mengenal", "Saling menjauhi", "Saling menguasai"], answer: 1, solution: "1. Islam melarang perpecahan dan permusuhan antarmanusia. 2. Dalam QS Al-Hujurat ayat 13 Allah menjelaskan manusia diciptakan bersuku-suku dan berbangsa-bangsa agar saling mengenal. 3. Jadi jawabannya agar saling mengenal." },
    { q: "Ukhuwah wathaniyah artinya persaudaraan ....", options: ["Sesama muslim", "Sebangsa dan setanah air", "Sesama manusia", "Satu keluarga"], answer: 1, solution: "1. Ukhuwah islamiyah persaudaraan seiman, ukhuwah basyariyah persaudaraan sesama manusia. 2. Ukhuwah wathaniyah adalah persaudaraan sebangsa dan setanah air. 3. Jadi jawabannya sebangsa dan setanah air." },
    { q: "Ukhuwah basyariyah artinya persaudaraan ....", options: ["Sesama muslim", "Sebangsa", "Sesama manusia", "Satu suku"], answer: 2, solution: "1. Ukhuwah islamiyah seiman, ukhuwah wathaniyah sebangsa. 2. Ukhuwah basyariyah adalah persaudaraan sesama manusia tanpa memandang agama dan bangsa. 3. Jadi jawabannya sesama manusia." },
    { q: "Tidak ada paksaan dalam memeluk agama dijelaskan dalam QS ....", options: ["Al-Baqarah ayat 256", "Al-Kafirun ayat 6", "Al-Hujurat ayat 13", "An-Nisa ayat 36"], answer: 0, solution: "1. Al-Kafirun ayat 6 tentang bagimu agamamu bagiku agamaku, Al-Hujurat ayat 13 tentang saling mengenal. 2. Prinsip tidak ada paksaan dalam agama terdapat dalam QS Al-Baqarah ayat 256. 3. Jadi jawabannya QS Al-Baqarah ayat 256." },
    { q: "Tasamuh artinya ....", options: ["Toleransi", "Permusuhan", "Fanatisme", "Egoisme"], answer: 0, solution: "1. Permusuhan, fanatisme, dan egoisme bertentangan dengan ajaran Islam. 2. Tasamuh artinya toleransi, yaitu menghargai perbedaan dan tidak memaksakan kehendak. 3. Jadi tasamuh artinya toleransi." },
    { q: "Batas toleransi dalam akidah adalah ....", options: ["Tidak mencampuradukkan akidah", "Mengikuti ibadah agama lain", "Mengubah keyakinan", "Meninggalkan salat"], answer: 0, solution: "1. Toleransi dalam Islam tidak berarti mencampuradukkan keyakinan. 2. QS Al-Kafirun menegaskan bagimu agamamu dan bagiku agamaku, sehingga akidah tidak boleh dicampuradukkan. 3. Jadi batasnya adalah tidak mencampuradukkan akidah." },
    { q: "Contoh sikap toleransi di sekolah adalah ....", options: ["Menghormati teman yang berbeda agama", "Memaksa teman mengikuti agamamu", "Mengejek keyakinan teman", "Menjauhi teman beda agama"], answer: 0, solution: "1. Memaksa, mengejek, dan menjauhi teman beda agama bukan toleransi. 2. Toleransi di sekolah diwujudkan dengan menghormati teman yang berbeda agama dan tetap bergaul baik. 3. Jadi contohnya adalah menghormati teman yang berbeda agama." },
    { q: "Sikap Nabi terhadap tetangga nonmuslim adalah ....", options: ["Memusuhinya", "Berbuat baik dan menghormatinya", "Mengusirnya", "Mengabaikannya"], answer: 1, solution: "1. Nabi SAW adalah teladan akhlak mulia bagi seluruh alam. 2. Nabi berbuat baik dan menghormati tetangga nonmuslim, bahkan menjenguknya saat sakit. 3. Jadi sikap Nabi adalah berbuat baik dan menghormatinya." },
    { q: "Jumlah surah dalam Al-Quran ada ....", options: ["110", "114", "116", "120"], answer: 1, solution: "1. Al-Quran terdiri dari 30 juz dengan ribuan ayat. 2. Jumlah surah dalam Al-Quran ada 114, diawali Al-Fatihah dan diakhiri An-Nas. 3. Jadi jumlahnya 114 surah." },
    { q: "Jumlah juz dalam Al-Quran ada ....", options: ["25", "30", "33", "40"], answer: 1, solution: "1. Pembagian juz memudahkan pembacaan dan penghafalan Al-Quran. 2. Al-Quran dibagi menjadi 30 juz yang sama panjang. 3. Jadi jumlahnya 30 juz." },
    { q: "Wahyu pertama yang turun kepada Nabi adalah ....", options: ["QS Al-Alaq ayat 1-5", "QS Al-Fatihah ayat 1-7", "QS Al-Baqarah ayat 1-5", "QS An-Nas ayat 1-6"], answer: 0, solution: "1. Al-Fatihah adalah surah pertama dalam mushaf, An-Nas surah terakhir. 2. Wahyu pertama turun di Gua Hira berupa QS Al-Alaq ayat 1 sampai 5. 3. Jadi jawabannya QS Al-Alaq ayat 1-5." },
    { q: "Wahyu terakhir yang turun adalah ....", options: ["QS Al-Maidah ayat 3", "QS Al-Alaq ayat 1", "QS Al-Fatihah ayat 5", "QS An-Nas ayat 6"], answer: 0, solution: "1. Al-Alaq ayat 1 adalah wahyu pertama, Al-Fatihah adalah pembuka mushaf. 2. Wahyu terakhir yang turun adalah QS Al-Maidah ayat 3 tentang kesempurnaan agama Islam. 3. Jadi jawabannya QS Al-Maidah ayat 3." },
    { q: "Al-Quran diturunkan secara berangsur-angsur selama ....", options: ["10 tahun", "13 tahun", "23 tahun", "40 tahun"], answer: 2, solution: "1. Al-Quran tidak turun sekaligus melainkan bertahap. 2. Al-Quran diturunkan selama kurang lebih 23 tahun: 13 tahun di Mekah dan 10 tahun di Madinah. 3. Jadi jawabannya 23 tahun." },
    { q: "Surah Makkiyah adalah surah yang turun ....", options: ["Sebelum hijrah di Mekah", "Setelah hijrah di Madinah", "Di Gua Hira saja", "Di Masjidil Aqsa"], answer: 0, solution: "1. Surah Madaniyah turun setelah hijrah di Madinah. 2. Surah Makkiyah adalah surah yang turun sebelum hijrah di Mekah, umumnya tentang akidah dan keimanan. 3. Jadi jawabannya sebelum hijrah di Mekah." },
    { q: "Adab membaca Al-Quran adalah ....", options: ["Dalam keadaan suci dan membaca taawuz", "Sambil berbaring santai", "Dengan suara keras mengganggu", "Sambil makan dan minum"], answer: 0, solution: "1. Membaca Al-Quran adalah ibadah yang memiliki adab. 2. Adabnya antara lain dalam keadaan suci (berwudu), membaca taawuz, dan membacanya dengan tartil. 3. Jadi jawabannya dalam keadaan suci dan membaca taawuz." },
    { q: "Hukum bacaan nun sukun bertemu huruf halqiyah (tenggorokan) adalah ....", options: ["Izhar", "Idgham", "Iqlab", "Ikhfa"], answer: 0, solution: "1. Idgham meleburkan bacaan, iqlab mengubah menjadi mim, ikhfa menyamarkan. 2. Nun sukun atau tanwin bertemu enam huruf halqiyah dibaca jelas tanpa dengung, hukumnya izhar. 3. Jadi hukumnya izhar." },
    { q: "Huruf idgham bighunnah ada empat, yaitu ....", options: ["Ya, nun, mim, wawu", "Lam dan ra", "Ba saja", "Qaf, tha, ba, jim, dal"], answer: 0, solution: "1. Lam dan ra adalah idgham bilaghunnah, ba adalah iqlab. 2. Idgham bighunnah (melebur dengan dengung) terjadi pada huruf ya, nun, mim, dan wawu. 3. Jadi hurufnya adalah ya, nun, mim, wawu." },
    { q: "Hukum bacaan nun sukun bertemu huruf ba adalah ....", options: ["Izhar", "Idgham", "Iqlab", "Ikhfa"], answer: 2, solution: "1. Izhar dibaca jelas, idgham dilebur, ikhfa disamarkan. 2. Nun sukun atau tanwin bertemu huruf ba diubah menjadi bunyi mim dengan dengung, hukumnya iqlab. 3. Jadi hukumnya iqlab." },
    { q: "Jumlah huruf ikhfa ada ....", options: ["6", "10", "15", "28"], answer: 2, solution: "1. Huruf izhar ada 6, idgham ada 6, iqlab hanya 1 (ba). 2. Sisa huruf hijaiyah selain huruf izhar, idgham, dan iqlab berjumlah 15 dan semuanya hukumnya ikhfa. 3. Jadi jumlah huruf ikhfa ada 15." },
    { q: "Mad thabii dibaca panjang sebanyak ....", options: ["Satu harakat", "Dua harakat", "Lima harakat", "Enam harakat"], answer: 1, solution: "1. Mad thabii adalah mad asli tanpa sebab hamzah atau sukun. 2. Panjang bacaannya adalah dua harakat atau satu alif. 3. Jadi mad thabii dibaca dua harakat." },
    { q: "Huruf qalqalah terkumpul dalam lafaz ....", options: ["Quthbu jadin", "Yarmalun", "Huruful halqi", "Syafawiyah"], answer: 0, solution: "1. Yarmalun adalah huruf idgham, huruful halqi adalah huruf izhar. 2. Lima huruf qalqalah (qaf, tha, ba, jim, dal) terkumpul dalam lafaz quthbu jadin. 3. Jadi jawabannya quthbu jadin." },
    { q: "Hadis adalah ....", options: ["Segala perkataan, perbuatan, dan ketetapan Nabi SAW", "Firman Allah dalam Al-Quran", "Pendapat para sahabat", "Cerita rakyat Arab"], answer: 0, solution: "1. Firman Allah adalah Al-Quran, pendapat sahabat bukan hadis. 2. Hadis adalah segala perkataan, perbuatan, dan ketetapan (taqrir) Nabi Muhammad SAW. 3. Jadi hadis adalah segala perkataan, perbuatan, dan ketetapan Nabi SAW." },
    { q: "Perawi hadis artinya ....", options: ["Pembawa atau penyampai hadis", "Penulis Al-Quran", "Penerjemah kitab", "Penghafal Al-Quran"], answer: 0, solution: "1. Sanad adalah mata rantai perawi, matan adalah isi hadis. 2. Perawi adalah orang yang membawa dan menyampaikan hadis dari Nabi secara turun-temurun. 3. Jadi perawi artinya pembawa atau penyampai hadis." },
    { q: "Fungsi hadis terhadap Al-Quran adalah ....", options: ["Menjelaskan dan merinci isi Al-Quran", "Menggantikan Al-Quran", "Bertentangan dengan Al-Quran", "Tidak berkaitan dengan Al-Quran"], answer: 0, solution: "1. Hadis adalah sumber hukum Islam kedua setelah Al-Quran. 2. Fungsi hadis (bayan) adalah menjelaskan dan merinci ayat-ayat Al-Quran yang masih umum. 3. Jadi fungsinya adalah menjelaskan dan merinci isi Al-Quran." },
    { q: "Hadis dhaif artinya hadis yang ....", options: ["Lemah sanadnya", "Sahih dan kuat", "Palsu", "Tidak ada artinya"], answer: 0, solution: "1. Hadis sahih sanadnya kuat dan bersambung, hadis palsu (maudhu) bukan sabda Nabi. 2. Hadis dhaif artinya hadis yang lemah, yaitu tidak memenuhi syarat hadis sahih atau hasan. 3. Jadi hadis dhaif artinya hadis yang lemah sanadnya." },
    { q: "Sanad hadis artinya ....", options: ["Mata rantai perawi hadis", "Isi atau teks hadis", "Judul kitab hadis", "Nama pengarang kitab"], answer: 0, solution: "1. Matan adalah isi atau teks hadis. 2. Sanad adalah mata rantai para perawi yang menyampaikan hadis dari Nabi hingga pencatatnya. 3. Jadi sanad artinya mata rantai perawi hadis." },
  ]
};
